import {icon,packArt,componentIcon} from './art.js';
import {esc,kg,yardSVG,deckSVG,outline,planFrame,DEFAULT_VIEW,overlap,containsRect,fitsPolygon,idleWorker,idleForklift,heavyTruck,truckStage} from './visual.js';
const loadView=()=>{try{const v=JSON.parse(localStorage.getItem('yardview')||'null');return v&&typeof v.zoom==='number'?{...DEFAULT_VIEW,...v}:{...DEFAULT_VIEW};}catch{return {...DEFAULT_VIEW};}};
let planView=loadView(),suppressPlanClick=false;
const saveView=()=>{try{localStorage.setItem('yardview',JSON.stringify(planView));}catch{}};
const applyView=()=>{const svg=document.querySelector('.scene .yard-svg'),g=svg?.querySelector('#plan');if(!g||!state?.yards[0])return;g.setAttribute('transform',planFrame(state.yards[0],planView).matrix);document.querySelector('#zoom-level')?.replaceChildren(document.createTextNode(Math.round(planView.zoom*100)+'%'));};
const planPoint=(svg,e)=>{const g=svg.querySelector('#plan')??svg;const point=svg.createSVGPoint();point.x=e.clientX;point.y=e.clientY;return point.matrixTransform(g.getScreenCTM().inverse());};
let selectedWorker=null,workerMoveMode=false,placementDraft=null,placementSequence=0,placementTimer=null;
const STEPS=[-100,-10,-5,-1,1,5,10,100];const loadStep=()=>{try{const n=Number(localStorage.getItem('yardstep'));return STEPS.includes(n)?n:1;}catch{return 1;}};
let step=loadStep(),stockReason='Sold to customer',gridSearch={},layoutDraft=null,layoutCheck=null,fixtureRows=null,placingFixture=null,planDragging=false,pinnedSite=null,heldSite=null,overviewSearch='',siteSearch='',openRows=new Set(),skillsOpen=new Set(),moveTarget=new Map(),mountChoice=new Map(),allocateChoice=new Map(),giveWorker=new Map(),jobDraft={},crewFilter='All',returnView=null;
let app,api,notify,account,settings,state,view='HOME',selected=null,poll=null,segments=[],closed=false,editingYard=null,historyCursor=0,containerPage=0,componentTab='ALL',stockTab='REGISTER',editingSite=null,intakeTab=null,intakeSearch='',intakeKind='PURCHASE';
const NAV=[['HOME','Home'],['OVERVIEW','Overview'],['WORKERS','Workers'],['EQUIPMENT','Equipment'],['TRUCK12','Truck 12.5 tonne'],['TRUCK2','Truck 2 tonne'],['STOCK','Stock'],['MATERIALS','Materials list'],['SITES','Client sites'],['YARD','Yard (layout plan)']];
const options=(items,label='name',current=null)=>items.map(x=>`<option value="${esc(x.id)}" ${x.id===current?'selected':''}>${esc(x[label])}</option>`).join('');
const select=(name,label,items)=>`<label>${label}<select name="${name}" required>${options(items)}</select></label>`;
const number=(name,label,value,min=0)=>`<label>${label}<input type="number" name="${name}" value="${value}" min="${min}" step="1" required></label>`;
const text=(name,label,value='')=>`<label>${label}<input name="${name}" value="${esc(value)}" required maxlength="250"></label>`;
const qty=(name='quantity',value=100)=>`${number(name,name==='workers'?'Workers':'Quantity',value)}<div class="quantity-buttons">${(name==='workers'?[-10,-5,-1,1,5,10]:[-100,-10,-5,-1,1,5,10,100]).map(n=>`<button type="button" class="secondary" data-adjust="${name}" data-delta="${n}">${n>0?'+':''}${n}</button>`).join('')}</div>`;
const name=id=>[...state.containers,...state.products,...state.yards,...state.sites,...state.trucks,...state.resources].find(x=>x.id===id)?.name??'Handling equipment';
const form=(id,title,content,button)=>`<details class="panel"><summary>${title}</summary><form id="${id}">${content}<div class="actions"><button>${button}</button></div></form></details>`;
async function command(action,data){const res=await fetch(`/api/commands/${action}`,{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':crypto.randomUUID()},body:JSON.stringify(data)});const result=await res.json();if(!res.ok)throw new Error(result.error);return result;}
function bind(id,action,transform=x=>x,after=null){const node=document.getElementById(id);if(!node)return;node.onsubmit=async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(node));node.querySelectorAll('input[type=number]').forEach(i=>{if(i.name)data[i.name]=i.value===''?null:Number(i.value);});const button=node.querySelector('button[type=submit],button:not([type])');if(button)button.disabled=true;try{const result=await command(action,transform(data));notify(result?.message??'Saved.');after?.(result);await refresh(true);}catch(e){notify(e.message);}finally{if(button)button.disabled=false;}};}
function action(selector,handler){document.querySelectorAll(selector).forEach(el=>el.onclick=async()=>{try{await handler(el);await refresh(true);}catch(e){notify(e.message);}});}
export function stopOperations(){clearInterval(poll);poll=null;}
export async function openOperations(root,apiCall,notifyCall,userState,settingsCallback){if(account?.company.id!==userState.company.id||account?.user.id!==userState.user.id){view='HOME';selected=null;selectedWorker=null;containerPage=0;componentTab='ALL';stockTab='REGISTER';editingYard=null;editingSite=null;intakeTab=null;intakeSearch='';segments=[];closed=false;layoutDraft=null;layoutCheck=null;fixtureRows=null;placingFixture=null;gridSearch={};pinnedSite=null;heldSite=null;overviewSearch='';siteSearch='';openRows=new Set();skillsOpen=new Set();jobDraft={};crewFilter='All';returnView=null;}app=root;api=apiCall;notify=notifyCall;account=userState;settings=settingsCallback;stopOperations();await refresh(true);poll=setInterval(()=>{if(!planDragging&&!document.querySelector('dialog[open]')&&!document.activeElement?.matches('input:not([data-live-search]),select,textarea')&&!document.querySelector('details[open]'))refresh(false).catch(e=>{if(e.status===401)stopOperations();});},1000);}
let refreshing=false;
const projection=s=>{const plan=['HOME','YARD'].includes(view);return JSON.stringify(s,(k,v)=>k==='progress'||k==='cooldownSeconds'||k==='remainingMs'||k==='cooldownMs'||k==='version'||(!plan&&(k==='x'||k==='y'||k==='walk'||k==='due'||k==='path'))?undefined:v);};
function patchVolatile(){document.querySelectorAll('[data-progress]').forEach(el=>{const id=el.dataset.progress,j=(state.jobs??[]).find(j=>j.id===id),w=state.resources.find(r=>r.id===id),p=j?j.progress:w?.board?.now?.progress;if(p==null)return;const bar=el.firstElementChild;if(bar)bar.style.width=p+'%';const t=document.querySelector('[data-progress-text="'+id+'"]');if(t)t.textContent=p+'%';});}
async function refresh(force){if(refreshing&&!force)return;refreshing=true;try{const next=await api(`state?page=${containerPage}`);const changed=force||projection(next)!==projection(state);state=next;if(changed)render();else patchVolatile();}finally{refreshing=false;}}
function render(){const scrolls=new Map([...document.querySelectorAll('.stockpile[data-grid]')].map(el=>[el.dataset.grid,el.querySelector('.tile-grid')?.scrollTop??0]));const keep=new Map([...document.querySelectorAll('[data-keep-scroll]')].map(el=>[el.dataset.keepScroll,el.scrollTop]));const focus=(()=>{const a=document.activeElement;if(!a||a===document.body)return null;if(a.matches('input[data-live-search]'))return {id:a.id,start:a.selectionStart,end:a.selectionEnd};const scope=a.closest('[data-focus-scope]');return scope?{scope:scope.dataset.focusScope,i:[...scope.querySelectorAll('button,a,input,select,[tabindex]')].indexOf(a)}:null;})();document.onkeydown=null;app.onpointerover=null;app.onkeydown=null;const oldWorkerPositions=new Map([...document.querySelectorAll('[data-worker],[data-forklift]')].map(el=>[el.dataset.worker??el.dataset.forklift,el.getAttribute('transform')]));const ops=account.permissions.includes('operations.manage');app.innerHTML=`<div class="workspace"><aside class="sidebar"><div class="workspace-tag">OPERATIONS WORKSPACE</div><div class="company-label">${esc(account.company.name)}</div><nav aria-label="Main navigation">${NAV.map(([v,label])=>`<button class="nav-button ${v===view?'current':''}" data-view="${v}">${icon(v)} <span>${label}</span></button>`).join('')}<button class="nav-button" id="settings">${icon('ACCOUNT')} <span>Account</span></button></nav><div class="sidebar-note">SIMULATION<br><small>Synthetic stock.<br>Server-controlled movements.</small></div></aside><section class="content"><div class="row"><div><div class="eyebrow">SCAFFOLD / ${esc(NAV.find(n=>n[0]===view)?.[1]??view)}</div><h1>${{HOME:'Your yard. Run it from here.',OVERVIEW:'Your yard at a glance.',WORKERS:'Your crew.',EQUIPMENT:'Forklifts, cranes and trucks.',TRUCK12:'12.5 tonne trucks. Ready for the next load.',TRUCK2:'2 tonne trucks. Quick runs and returns.',STOCK:'Every piece accounted for.',MATERIALS:'Every component you can order.',SITES:'From yard to site.',YARD:'A place for everything.'}[view]??''}</h1></div>${state.config&&ops?`<button class="secondary" id="pause">${state.config.paused?'Resume simulation':'Pause simulation'}</button>`:''}</div><div class="simulation-banner"><span class="status-dot"></span> SIMULATION / DEMONSTRATION <span>Not real lifting operations or certified load engineering.</span></div>${ops&&!state.yards.length?'<p class="notice">Start here: draw your yard → configure resources → add starting stock → open your yard.</p>':''}<div id="view">${view==='HOME'?homeView():view==='OVERVIEW'?overviewView():view==='WORKERS'?workersView():view==='EQUIPMENT'?equipmentView():view==='TRUCK12'?truckView(t=>t.payload>=10000000):view==='TRUCK2'?truckView(t=>t.payload<10000000):view==='STOCK'?stockView():view==='MATERIALS'?materialsView():view==='SITES'?siteView()+requestView():view==='YARD'?yardView():overviewView()}</div>${selected&&!(['YARD','HOME'].includes(view)&&state.containers.some(c=>c.id===selected&&c.location===state.yards[0]?.id))?detail():''}<section class="activity"><div class="row"><h2>Movement activity</h2><span class="muted">${state.tasks.length} active tasks</span></div>${state.tasks.length?state.tasks.map(t=>`<div class="task"><div><strong>${esc(name(t.container))}</strong> <span class="badge">${esc(t.layout?'LAYOUT '+(t.park?'SET DOWN':'STEP')+' '+t.step:t.type)}</span>${t.priority?` <span class="badge">P${t.priority}</span>`:''}<p>${t.title?esc(t.title)+' · ':''}${esc(t.state.replaceAll('_',' '))} · ${esc(name(t.from))} → ${esc(name(t.to))}${t.reason?`<br><span class="error-text">${esc(t.reason)}</span>`:''}</p></div><div>${t.state==='BLOCKED'?`<button class="secondary" data-retry="${t.id}">Retry</button>`:''}${!t.picked?`<button class="secondary" data-cancel="${t.id}">Cancel</button>`:''}</div></div>`).join(''):'<p class="muted">No movements waiting. Material stays where it is until you request a move.</p>'}</section><details class="panel"><summary>Notifications · ${state.notifications.length}</summary>${state.notifications.slice().reverse().map(n=>`<p><strong>${esc(n.title)}</strong><br>${esc(n.body)}</p>`).join('')||'<p>No notifications yet.</p>'}</details></section></div>`;
  for(const [id,top] of scrolls){const el=document.querySelector('.stockpile[data-grid="'+id+'"] .tile-grid');if(el)el.scrollTop=top;}for(const [id,top] of keep){const el=document.querySelector('[data-keep-scroll="'+id+'"]');if(el)el.scrollTop=top;}
  document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;selected=null;pinnedSite=null;heldSite=null;returnView=null;if(workerMoveMode!=='PLACE')workerMoveMode=false;if(!['YARD','HOME'].includes(view)){layoutDraft=null;layoutCheck=null;}render();});document.querySelector('#settings').onclick=()=>{stopOperations();settings();};
  document.querySelector('#pause')?.addEventListener('click',async()=>{try{await command('pause',{paused:!state.config.paused});await refresh(true);}catch(e){notify(e.message);}});
  document.querySelectorAll('[data-retire]').forEach(b=>b.onclick=async()=>{const id=b.dataset.retire;if(!confirm('Remove '+(b.dataset.retireLabel||'this item')+' from the yard?'))return;try{await command('retire',{id});if(selectedWorker===id)selectedWorker=null;if(selected===id)selected=null;notify('Removed.');await refresh(true);}catch(e){notify(e.message);}});
  document.querySelectorAll('[data-intake-tab]').forEach(b=>b.onclick=()=>{intakeTab=b.dataset.intakeTab;render();});
  document.querySelector('#intake-search')?.addEventListener('input',e=>{intakeSearch=e.target.value;const q=intakeSearch.trim().toLowerCase();document.querySelectorAll('[data-intake-row]').forEach(row=>row.hidden=!!q&&!row.textContent.toLowerCase().includes(q));});
  document.querySelector('#intake-kind')?.addEventListener('change',e=>{intakeKind=e.target.value;});
  document.querySelectorAll('[data-intake]').forEach(b=>b.onclick=async()=>{const product=b.dataset.intake,quantity=Number(document.querySelector('[data-intake-qty="'+product+'"]').value);if(!(quantity>0)){notify('Enter a quantity of at least 1.');return;}b.disabled=true;try{const r=await command('stockIntake',{location:state.yards[0].id,product,quantity,kind:intakeKind});notify(r.message);await refresh(true);}catch(e){notify(e.message);b.disabled=false;}});
  document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{step=Number(b.dataset.step);try{localStorage.setItem('yardstep',String(step));}catch{}render();});
  document.querySelectorAll('[data-grid-search]').forEach(i=>i.oninput=()=>{gridSearch[i.dataset.gridSearch]=i.value;applyGridSearch(i.closest('.stockpile'));});document.querySelectorAll('.stockpile[data-grid]').forEach(applyGridSearch);
  document.querySelector('#stock-reason')?.addEventListener('change',e=>{stockReason=e.target.value;});
  document.querySelectorAll('[data-tile]').forEach(b=>b.onclick=async()=>{const product=b.dataset.tile,n=step;b.classList.add('pressed');try{const r=n>0?await command('stockIntake',{location:state.yards[0].id,product,quantity:n,kind:intakeKind}):await command('stockRemoval',{location:state.yards[0].id,product,quantity:-n,reason:stockReason});notify(r.message);await refresh(true);}catch(e){notify(e.message);b.classList.remove('pressed');}});
  document.querySelector('#planner-start')?.addEventListener('click',()=>{layoutDraft={moves:{}};layoutCheck=null;selected=null;selectedWorker=null;workerMoveMode=false;returnView=null;render();});
  document.querySelector('#planner-exit')?.addEventListener('click',()=>{layoutDraft=null;layoutCheck=null;render();});
  document.querySelector('#planner-clear')?.addEventListener('click',()=>{layoutDraft={moves:{}};layoutCheck=null;render();});
  document.querySelectorAll('[data-unplan]').forEach(b=>b.onclick=()=>{unplan(b.dataset.unplan);layoutCheck=null;render();});
  document.querySelector('#planner-check')?.addEventListener('click',async()=>{try{layoutCheck=await api('layout-preview',{yard:state.yards[0].id,moves:plannedMoves()});}catch(e){layoutCheck={ok:false,message:e.message,steps:[]};}render();});
  document.querySelector('#planner-commit')?.addEventListener('click',async()=>{const button=document.querySelector('#planner-commit');button.disabled=true;try{const r=await command('commitLayout',{yard:state.yards[0].id,moves:plannedMoves(),name:'Layout plan '+new Date().toLocaleString()});layoutDraft=null;layoutCheck=null;notify(r.message+(r.warnings?.length?' '+r.warnings.join(' '):''));await refresh(true);}catch(e){notify(e.message);button.disabled=false;}});
  action('[data-cancel-layout]',e=>command('cancelLayout',{id:e.dataset.cancelLayout}));
  action('[data-quick]',e=>{const [kind,delta]=e.dataset.quick.split(':');const truck=kind==='TRUCK2'?2000000:kind==='TRUCK12'?12500000:null;return command('quickAdjust',{kind:truck?'TRUCK':kind,delta:Number(delta),location:state.yards[0].id,...(truck?{payload:truck}:{})});});
  action('[data-retry]',e=>command('retry',{id:e.dataset.retry}));action('[data-cancel]',e=>command('cancel',{id:e.dataset.cancel}));
  document.querySelectorAll('[data-select]').forEach(el=>{const pick=()=>{if(suppressPlanClick)return;selected=el.dataset.select;render();document.querySelector('.selected-detail')?.scrollIntoView({block:'nearest',behavior:'smooth'});};el.onclick=pick;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();pick();}};});
  document.querySelectorAll('[data-adjust]').forEach(b=>b.onclick=()=>{const input=b.closest('form').querySelector(`[name="${b.dataset.adjust}"]`);input.value=Math.max(0,Number(input.value)+Number(b.dataset.delta));});
  document.querySelectorAll('[draggable=true]').forEach(el=>el.ondragstart=e=>{e.dataTransfer.setData('text/plain',el.dataset.select);e.dataTransfer.effectAllowed='move';el.classList.add('drag-ghost');el.ondragend=()=>el.classList.remove('drag-ghost');});
  document.querySelectorAll('[data-drop]').forEach(el=>{el.ondragover=e=>{e.preventDefault();el.classList.add('drop-target');};el.ondragleave=()=>el.classList.remove('drop-target');el.ondrop=async e=>{e.preventDefault();el.classList.remove('drop-target');try{await command('queue',{container:e.dataTransfer.getData('text/plain'),destination:el.dataset.drop});notify('Move requested. A worker and machine will perform it.');await refresh(true);}catch(error){notify(error.message);}};});
  if(state.containerCount>100){document.querySelector('#view').insertAdjacentHTML('afterbegin',`<div class="actions"><button class="secondary" id="prev-page" ${containerPage===0?'disabled':''}>Previous 100 stillages / cages</button><span>Stillages / cages ${containerPage*100+1}?${Math.min((containerPage+1)*100,state.containerCount)} of ${state.containerCount}</span><button class="secondary" id="next-page" ${(containerPage+1)*100>=state.containerCount?'disabled':''}>Next 100 stillages / cages</button></div>`);document.querySelector('#prev-page').onclick=()=>{containerPage--;refresh(true);};document.querySelector('#next-page').onclick=()=>{containerPage++;refresh(true);};}
  if(!matchMedia('(prefers-reduced-motion: reduce)').matches)document.querySelectorAll('[data-worker],[data-forklift]').forEach(el=>{const before=oldWorkerPositions.get(el.dataset.worker??el.dataset.forklift),after=el.getAttribute('transform');if(before&&before!==after){const css=t=>t.replace(/translate\(([-.0-9]+) ([-.0-9]+)\)/,'translate($1px, $2px)');el.animate([{transform:css(before)},{transform:css(after)}],{duration:900,easing:'linear'});}});
  bindWorkers();
  bindViews();
  if(view==='WORKERS')bindWorkersPage();
  if(focus&&document.activeElement===document.body){if(focus.id){const i=document.getElementById(focus.id);if(i){i.focus({preventScroll:true});try{i.setSelectionRange(focus.start,focus.end);}catch{}}}else document.querySelector('[data-focus-scope="'+focus.scope+'"]')?.querySelectorAll('button,a,input,select,[tabindex]')[focus.i]?.focus({preventScroll:true});}
}

const quickRow=(kind,word,count,label)=>{const yard=state.yards[0];if(!yard||!account.permissions.includes('operations.manage'))return '';return '<div class="quick-row"><span>'+label+'</span><button type="button" class="secondary" data-quick="'+kind+':-1" '+(count?'':'disabled')+'>&minus;1 '+word+'</button><strong>'+count+'</strong><button type="button" data-quick="'+kind+':1">+1 '+word+'</button></div>';};
function intakePanel(){const yard=state.yards[0];if(!yard||!account.permissions.includes('stock.adjust'))return '';const systems=account.systems.filter(s=>s.enabled);if(!systems.some(s=>s.id===intakeTab))intakeTab=systems[0]?.id??null;const products=state.products.filter(p=>!p.retired&&p.system===intakeTab).sort((a,b)=>(a.category??'').localeCompare(b.category??'')||a.name.localeCompare(b.name,undefined,{numeric:true}));const q=intakeSearch.trim().toLowerCase();return '<section class="panel" id="intake"><div class="row"><h2>Materials intake</h2><span class="muted">'+esc(yard.name)+'</span></div><p>Pick a system, find the material and add it to the yard. It goes into the first available stillage (empty, or already holding that material with room); when the yard runs out of stillages a new one is added on top of the shortest pile.</p><div class="subtabs" role="tablist">'+systems.map(sy=>'<button type="button" class="secondary '+(sy.id===intakeTab?'current':'')+'" data-intake-tab="'+esc(sy.id)+'" role="tab">'+esc(sy.name)+' <small>'+state.products.filter(p=>!p.retired&&p.system===sy.id).length+'</small></button>').join('')+'</div><div class="intake-tools"><label>Search this list<input id="intake-search" type="search" placeholder="Standard, ledger, coupler…" value="'+esc(intakeSearch)+'"></label><label>Record as<select id="intake-kind"><option value="PURCHASE" '+(intakeKind==='PURCHASE'?'selected':'')+'>Purchase</option><option value="ORIGINAL" '+(intakeKind==='ORIGINAL'?'selected':'')+'>Original stock</option></select></label></div><div class="table-scroll"><table aria-label="Materials intake"><thead><tr><th>Material</th><th>Category</th><th>Unit weight</th><th>Per stillage</th><th>Quantity</th><th></th></tr></thead><tbody>'+products.map(p=>{const hay=(p.name+' '+(p.category??'')+' '+(p.reference??'')).toLowerCase();return '<tr data-intake-row '+(q&&!hay.includes(q)?'hidden':'')+'><td><strong>'+esc(p.name)+'</strong><small>'+esc(p.reference??'')+'</small></td><td>'+esc(p.category??'')+'</td><td>'+kg(p.unitWeight)+'</td><td>'+(p.packQuantity??'no limit')+'</td><td><input type="number" min="1" step="1" value="'+(p.packQuantity??10)+'" data-intake-qty="'+p.id+'" aria-label="Quantity of '+esc(p.name)+'"></td><td><button type="button" data-intake="'+p.id+'">Add to yard</button></td></tr>';}).join('')+(products.length?'':'<tr><td colspan="6">No materials in this system yet. Import a catalogue under Settings.</td></tr>')+'</tbody></table></div></section>';}
function fleetColumn(yard){if(!yard||!account.permissions.includes('operations.manage'))return '';const workers=state.resources.filter(r=>r.type==='WORKER'&&r.location===yard.id).length,forklifts=state.resources.filter(r=>r.type==='FORKLIFT'&&r.location===yard.id).length,heavy=state.trucks.filter(t=>t.yard===yard.id&&t.payload>=10000000).length,light=state.trucks.filter(t=>t.yard===yard.id&&t.payload<10000000).length,stillages=state.containers.filter(c=>c.location===yard.id&&c.type==='STILLAGE').length;return '<div class="quick-grid fleet-column">'+quickRow('FORKLIFT','forklift',forklifts,'Forklift')+quickRow('WORKER','worker',workers,'Worker')+quickRow('STILLAGE','stillage',stillages,'Empty stillage')+quickRow('TRUCK2','truck',light,'Truck 2 tonne')+quickRow('TRUCK12','truck',heavy,'Truck 12.5 tonne')+'</div>';}
function crewTable(list){const row=r=>{const task=state.tasks.find(t=>t.id===r.task);return '<tr><td><span class="resource-avatar">'+(r.type==='WORKER'?'W':'M')+'</span><strong>'+esc(r.name)+'</strong><small>'+esc(r.type.replaceAll('_',' '))+'</small></td><td>'+esc(name(r.location))+'</td><td><span class="badge '+(!r.task&&!r.walk&&!r.mountedOn&&!r.driver&&!r.claimedBy&&r.workerMode!=='HOLD'?'available':'busy')+'">'+(r.task?'Assigned':r.mountedOn?'Mounted':r.driver?'Occupied':r.claimedBy?'Reserved':r.walk?'Moving':r.workerMode==='HOLD'?'Holding':'Available')+'</span></td><td>'+(task?esc(task.type.replaceAll('_',' ')+' - '+task.state.replaceAll('_',' '))+'<small>'+esc(name(task.container))+' - '+esc(name(task.to))+'</small>':r.task?'Assigned to movement':r.mountedOn?'Driving '+esc(name(r.mountedOn)):r.driver?'Driver: '+esc(name(r.driver)):r.claimedBy?'Worker approaching':r.walk?'Walking to destination':r.workerMode==='HOLD'?'Holding position':'Ready for the next task')+'</td>'+(account.permissions.includes('operations.manage')&&['WORKER','FORKLIFT'].includes(r.type)?'<td><button type="button" class="secondary" data-retire="'+esc(r.id)+'" data-retire-label="'+esc(r.name)+'" '+(r.task||r.walk||r.mountedOn||r.mountTarget||r.driver||r.claimedBy||r.cargo||r.drive?'disabled':'')+'>Remove</button></td>':'<td></td>')+'</tr>';};return '<div class="table-scroll"><table><thead><tr><th>Name</th><th>Location</th><th>Availability</th><th>Current task</th><th></th></tr></thead><tbody>'+list.map(row).join('')+'</tbody></table></div>';}
function workersView(){
 const ops=account.permissions.includes('operations.manage'),yard=state.yards[0],workers=state.resources.filter(r=>r.type==='WORKER'),cfg=state.config??{};
 if(!ops)return '<section class="panel"><div class="row"><h2>Workers</h2><span class="badge">'+workers.length+' on your sites</span></div><div class="table-scroll"><table><thead><tr><th>Name</th><th>Status</th><th>Now</th></tr></thead><tbody>'+(workers.map(r=>'<tr><td><strong>'+esc(r.name)+'</strong><small>'+esc(name(r.location))+'</small></td><td><span class="badge '+(r.task?'busy':'available')+'">'+(r.task?'Working':'Site crew')+'</span></td><td>'+esc(r.task?'On a crane move':'Standing by')+'</td></tr>').join('')||'<tr><td colspan="3">No crew on your sites yet.</td></tr>')+'</tbody></table></div></section>';
 const crew=yard?workers.filter(r=>r.location===yard.id):[],siteCrew=workers.filter(r=>!yard||r.location!==yard.id),now=Date.now();
 const statusOf=r=>r.task?(state.tasks.find(t=>t.id===r.task)?.skill==='TRUCK'?'Truck work':'Moving stock'):r.mountedOn?'Driving':r.mountTarget?'Walking to forklift':r.job?(r.walk?'Walking to job':'On yard job'):r.walk?'Walking':r.workerMode==='HOLD'?'Holding':r.assignHoldUntil&&Date.parse(r.assignHoldUntil)>now?'Standing by (grace)':'Standing by';
 const groupOf=s=>['Truck work','Moving stock'].includes(s)?'Working':['On yard job','Walking to job'].includes(s)?'On jobs':s==='Driving'?'Driving':s==='Holding'?'Holding':'Standing by';
 const tally=crew.reduce((m,r)=>{const g=groupOf(statusOf(r));m[g]=(m[g]??0)+1;return m;},{});
 const badge=crew.length+' in the yard'+['Working','On jobs','Driving','Standing by','Holding'].map(g=>tally[g]?' &middot; '+tally[g]+' '+g.toLowerCase():'').join('');
 const forkliftsFree=yard?state.resources.filter(r=>r.type==='FORKLIFT'&&r.location===yard.id&&!r.task&&!r.driver&&!r.claimedBy&&Number.isFinite(r.x)):[];
 const openJobs=(state.jobs??[]).filter(j=>j.state==='OPEN'&&j.effect!=='UNLOAD');
 const chip=g=>'<button type="button" class="secondary '+(crewFilter===g?'current':'')+'" data-crew-filter="'+g+'" role="tab" aria-selected="'+(crewFilter===g)+'">'+g+(g==='All'?' '+crew.length:tally[g]?' '+tally[g]:'')+'</button>';
 const row=r=>{const st=statusOf(r),g=groupOf(st),open=openRows.has(r.id),b=r.board,auto=!r.mountedOn&&r.workerMode!=='HOLD'&&r.workerMode!=='MOVING',m=r.mountedOn?state.resources.find(x=>x.id===r.mountedOn):null,canAllocate=!r.task&&!r.mountedOn&&!r.mountTarget,matching=openJobs.filter(j=>r.skills?.[j.category]!==false),skillsOff=(state.skillCatalogue??[]).filter(s=>r.skills?.[s.code]===false),task=state.tasks.find(t=>t.id===r.task);
  const jobOf=b?.now?.job?(state.jobs??[]).find(j=>j.id===b.now.job):null;
  const nowLine='<div class="board-line now"><b>NOW</b><span class="text" title="'+esc(b?.now?.title??st)+'">'+esc(b?.now?.title??st)+'</span>'+(b?.now?.progress!=null?'<i class="bar" data-progress="'+r.id+'"><span style="width:'+b.now.progress+'%"></span></i><small class="num" data-progress-text="'+r.id+'">'+b.now.progress+'%</small>':'')+(b?.now?.badge?'<span class="badge job-badge '+esc(b.now.badge)+'">'+({FORKLIFT:'Forklift job',ROUTINE:'Routine',HAZARD:'Hazard',REAL:'Real effect',CHECK:'Check',RECORDED:'Recorded work'}[b.now.badge]??esc(b.now.badge))+'</span>':'')+'</div>';
  const sendTo='<label class="mount-choice expanded-only">Send to<select data-move-target="'+r.id+'"><option value="plan" '+((moveTarget.get(r.id)??'plan')==='plan'?'selected':'')+'>Pick a spot on the plan</option>'+(yard?'<optgroup label="Yard"><option value="loading" '+(moveTarget.get(r.id)==='loading'?'selected':'')+'>Loading zone</option><option value="gate" '+(moveTarget.get(r.id)==='gate'?'selected':'')+'>Gate</option>'+(r.mountedOn?[]:(yard.fixtures??[])).map(f=>'<option value="'+esc(f.id)+'" '+(moveTarget.get(r.id)===f.id?'selected':'')+'>'+esc(f.name)+'</option>').join('')+'</optgroup>'+(forkliftsFree.length&&!r.mountedOn?'<optgroup label="Forklifts">'+forkliftsFree.map(f=>'<option value="'+f.id+'" '+(moveTarget.get(r.id)===f.id?'selected':'')+'>Beside '+esc(f.name)+'</option>').join('')+'</optgroup>':'')+(selected&&state.containers.some(c=>c.id===selected&&c.location===yard.id)?'<option value="'+selected+'" '+(moveTarget.get(r.id)===selected?'selected':'')+'>Selected stillage '+esc(name(selected))+'</option>':''):'')+'</select></label><button type="button" class="expanded-only" data-worker-order="MOVE" data-worker-id="'+r.id+'" '+(r.task?'disabled':'')+'>'+(r.mountedOn?'Drive':'Move')+'</button>';
  const mount='<label class="mount-choice expanded-only">Forklift<select data-mount-select="'+r.id+'" '+(r.mountedOn||!forkliftsFree.length?'disabled':'')+'>'+(forkliftsFree.length?options(forkliftsFree,'name',mountChoice.get(r.id)):'<option>No free forklift</option>')+'</select></label><button type="button" class="expanded-only" data-worker-order="MOUNT" data-worker-id="'+r.id+'" '+(r.task||r.mountTarget||r.mountedOn||!forkliftsFree.length?'disabled':'')+'>'+(r.mountTarget?'Walking to '+esc(name(r.mountTarget)):'Mount forklift')+'</button><button type="button" class="secondary expanded-only" data-worker-order="DISMOUNT" data-worker-id="'+r.id+'" '+(!r.mountedOn||r.task||m?.cargo||m?.drive?'disabled':'')+'>Unmount forklift</button>';
  const allocate='<label class="mount-choice expanded-only">Allocate<select data-allocate-select="'+r.id+'" '+(canAllocate&&matching.length?'':'disabled')+'>'+(matching.length?matching.slice(0,8).map(j=>'<option value="'+j.id+'" '+(allocateChoice.get(r.id)===j.id?'selected':'')+'>P'+j.priority+' \u2013 '+esc(j.title)+'</option>').join(''):'<option>Nothing open for these skills</option>')+'</select></label><button type="button" class="secondary expanded-only" data-allocate="'+r.id+'" '+(canAllocate&&matching.length?'':'disabled')+'>Allocate</button><button type="button" class="secondary expanded-only" data-take-off="'+(r.job??'')+'" '+(r.job?'':'disabled')+'>Take off</button>';
  return '<tr class="crew-row '+(open?'':'collapsed')+'" data-crew-row="'+r.id+'" data-group="'+g+'" data-focus-scope="worker:'+r.id+'" '+(crewFilter!=='All'&&crewFilter!==g?'hidden':'')+'><td><span class="resource-avatar">W</span><strong>'+esc(r.name)+'</strong><small>'+esc(name(r.location))+(r.mountedOn?' \u2013 '+esc(name(r.mountedOn)):'')+'</small><br><button type="button" class="text-button" data-row-open="'+r.id+'" aria-expanded="'+open+'">'+(open?'Less':'More')+'</button></td>'
   +'<td><span class="badge '+(['Standing by','Standing by (grace)','Holding'].includes(st)?'available':'busy')+'">'+st+'</span><br><button type="button" class="secondary mode-chip '+(auto?'current':'')+'" data-worker-order="'+(auto?'HOLD':'AUTO')+'" data-worker-id="'+r.id+'" aria-pressed="'+auto+'" '+(r.task||r.mountedOn?'disabled':'')+'>'+(r.mountedOn?'Driving':auto?'Automatic':r.workerMode==='MOVING'?'Manual \u2013 walking on orders':'Manual \u2013 holding')+'</button><small class="mode-note">'+(r.mountedOn?'Unmount to return to automatic work':auto?'Takes forklift moves and yard jobs. Press to hold in place.':r.workerMode==='MOVING'?'Press to forget the order and return to the pool':'Holding \u2013 press to return to automatic work')+'</small>'+(r.workerReason?'<br><span class="error-text">'+esc(r.workerReason)+'</span>':'')+(task?.reason?'<br><span class="error-text">'+esc(task.reason)+'</span>':'')+'</td>'
   +'<td class="board-cell">'+nowLine+'<div class="board-line expanded-only"><b>NEXT</b><span class="text">'+esc(b?.next?.title??'\u2013')+'</span></div><div class="board-line then expanded-only"><b>THEN</b><span class="text">'+esc(b?.then?.title??'\u2013')+'</span></div><div class="board-line idle expanded-only"><b>IDLE TASKS</b><span class="text">'+(b?.idle?.length?b.idle.map(j=>esc(j.title)).join(' \u00b7 '):r.workerMode==='HOLD'?'Holding \u2013 press Automatic to receive jobs':'Board clear \u2013 add a job below')+'</span></div></td>'
   +'<td class="skills-cell"><button type="button" class="secondary skill-chip" data-skills-open="'+r.id+'" aria-expanded="'+skillsOpen.has(r.id)+'">Skills '+(10-skillsOff.length)+'/10'+(skillsOff.length?' \u2013 '+skillsOff.map(s=>esc(s.short)).join(', ')+' off':'')+'</button><div class="skills-list">'+(skillsOpen.has(r.id)?(state.skillCatalogue??[]).map(s=>'<button type="button" class="skill-chip '+(r.skills?.[s.code]===false?'off':'on')+'" data-skill="'+s.code+'" data-worker-id="'+r.id+'" aria-pressed="'+(r.skills?.[s.code]!==false)+'" title="'+esc(s.label+': '+s.vocabulary.join(', '))+'">'+esc(s.short)+'</button>').join('')+'<p class="skill-vocab">'+(state.skillCatalogue??[]).map(s=>'<strong>'+esc(s.short)+'</strong>: '+esc(s.vocabulary.join(', '))).join(' \u00b7 ')+'</p>':'')+'</div></td>'
   +'<td><div class="worker-buttons"><button type="button" class="secondary" data-worker-order="STOP" data-worker-id="'+r.id+'" '+(r.task||!(r.walk||r.mountTarget||r.job||(r.mountedOn&&m?.drive))?'disabled':'')+'>Stop</button><button type="button" data-next-job="'+r.id+'" '+(canAllocate?'':'disabled')+'>Next up</button>'+sendTo+mount+allocate+'</div></td>'
   +'<td><button type="button" class="secondary" data-retire="'+esc(r.id)+'" data-retire-label="worker '+esc(r.name)+'" '+(r.task||(r.walk&&!r.walk.job)||r.mountedOn||r.mountTarget?'disabled':'')+'>Remove</button></td></tr>';};
 const ladder=yard&&state.ladder?.[yard.id]?'<ol class="ladder">'+state.ladder[yard.id].map(l=>'<li class="'+(l.open?'hot':'')+'">P'+l.priority+' '+esc(l.label)+' \u2013 '+l.open+' open \u00b7 '+l.working+' working'+(l.blocked?' \u00b7 '+l.blocked+' blocked':'')+'</li>').join('')+'</ol><p class="muted">Yard lists carry no dates yet: P2 = a truck is booked, P3 = still waiting for one. NEXT and THEN are likely, not promised: the forklift engine always has first pick.</p>':'';
 const head='<section class="panel workers-board"><div class="row"><h2>Workers</h2><span class="badge">'+badge+'</span></div><div class="worker-buttons crew-tools"><button type="button" class="secondary mode-chip '+(cfg.jobs!==false?'current':'')+'" data-jobs-mode="jobs" aria-pressed="'+(cfg.jobs!==false)+'">Automatic yard jobs: '+(cfg.jobs!==false?'On':'Off')+'</button><button type="button" class="secondary mode-chip '+(cfg.routineJobs!==false?'current':'')+'" data-jobs-mode="routineJobs" aria-pressed="'+(cfg.routineJobs!==false)+'">Routine work: '+(cfg.routineJobs!==false?'On':'Off')+'</button>'+(yard?'<button type="button" class="secondary" data-allocate-all>Allocate all idle</button><button type="button" class="secondary" data-all-auto>All automatic</button><button type="button" class="secondary" data-hold-all>Hold all</button>':'')+'</div>'+(cfg.jobsFault?'<p class="fault-note">Yard jobs paused: '+esc(cfg.jobsFault.message)+' <button type="button" class="secondary" data-jobs-mode="resume">Resume yard jobs</button></p>':'')+(yard?'<div class="quick-grid">'+quickRow('WORKER','worker',crew.length,'Yard workers')+'</div>':'<p class="notice">Draw your yard first; workers are added to it.</p>')+ladder+'<div class="subtabs" role="tablist">'+['All','Working','On jobs','Standing by','Holding','Driving'].map(chip).join('')+'</div>'+(crew.length?'<div class="table-scroll crew" data-keep-scroll="crew"><table class="crew"><thead><tr><th>Name</th><th>Status</th><th>Now / Next / Then</th><th>Skills</th><th>Orders</th><th></th></tr></thead><tbody>'+crew.map(row).join('')+'</tbody></table></div>':'<p class="muted">No workers yet. Use +1 worker to add your crew.</p>')+'</section>';
 return head+(yard?jobBoardPanel(yard,crew)+addJobPanel(yard,crew):'')+(siteCrew.length?'<section class="panel"><div class="row"><h2>Site crews</h2><span class="badge">'+siteCrew.length+' on sites</span></div>'+crewTable(siteCrew)+'<p class="muted">Site crews work the cranes at their sites; yard jobs and skills apply to the yard crew.</p></section>':'');
}
function jobBoardPanel(yard,crew){
 const jobs=(state.jobs??[]).filter(j=>j.yard===yard.id&&j.origin!=='ROUTINE'),tasks=state.tasks.filter(t=>t.handling===yard.id),labels=Object.fromEntries((state.ladder?.[yard.id]??[]).map(l=>[l.priority,l.label]));
 const open=jobs.filter(j=>['OPEN','BLOCKED'].includes(j.state)).length,working=jobs.filter(j=>['ASSIGNED','IN_PROGRESS'].includes(j.state)).length+tasks.filter(t=>t.resources?.length).length,blocked=jobs.filter(j=>j.state==='BLOCKED').length+tasks.filter(t=>t.state==='BLOCKED').length;
 const taskRow=t=>'<tr data-focus-scope="task:'+t.id+'"><td>P'+t.priority+'</td><td><strong>'+esc(t.title??t.type)+'</strong> <span class="badge">Forklift job</span><small>'+esc(t.state.replaceAll('_',' '))+'</small></td><td>'+esc(name(t.from))+' \u2192 '+esc(name(t.to))+'</td><td>'+(t.resources?.length?esc(t.resources.slice(1).map(id=>name(id)).join(', ')||name(t.resources[0])):'waiting for a forklift')+'</td><td>'+(t.reason?'<span class="error-text">'+esc(t.reason)+'</span>':esc(t.state.replaceAll('_',' ').toLowerCase()))+'</td><td>'+(t.state==='BLOCKED'?'<button type="button" class="secondary" data-retry="'+t.id+'">Retry</button>':'')+(!t.picked?'<button type="button" class="secondary" data-cancel="'+t.id+'">Cancel</button>':'')+'</td></tr>';
 const jobRow=j=>{const eligible=crew.filter(w=>w.skills?.[j.category]!==false&&!w.task&&!w.mountedOn&&!w.mountTarget);return '<tr data-focus-scope="job:'+j.id+'"><td>P'+j.priority+'</td><td><strong>'+esc(j.title)+'</strong> <span class="badge job-badge '+(j.hazard?'HAZARD':esc(j.badge))+'">'+(j.hazard?'Hazard':j.badge==='REAL'?'Real effect':j.badge==='CHECK'?'Check':'Recorded work')+'</span>'+(j.detail?'<small>'+esc(j.detail)+'</small>':'')+'</td><td>'+esc(j.subject?.name??(j.target?'Set spot':'Anywhere'))+'</td><td>'+esc(j.workerName??'\u2013')+'</td><td>'+(j.state==='IN_PROGRESS'?'<i class="bar" data-progress="'+j.id+'"><span style="width:'+j.progress+'%"></span></i> <small class="num" data-progress-text="'+j.id+'">'+j.progress+'%</small>':j.state==='ASSIGNED'?'Walking':j.state==='BLOCKED'?'<span class="error-text">Blocked: '+esc(j.blocked)+'</span>':j.cooldownSeconds>0?'Retrying in '+j.cooldownSeconds+' s':'Open')+(j.reason&&j.state==='OPEN'?'<br><small>'+esc(j.reason)+'</small>':'')+'</td><td class="board-actions">'+(['OPEN','BLOCKED'].includes(j.state)&&(j.state==='OPEN'||j.failures>0)?(eligible.length?'<select data-give-worker="'+j.id+'">'+eligible.map(w=>'<option value="'+w.id+'" '+(giveWorker.get(j.id)===w.id?'selected':'')+'>'+esc(w.name)+(w.job?' (on a job)':'')+'</option>').join('')+'</select><button type="button" class="secondary" data-give-job="'+j.id+'">Allocate</button>':'<small class="muted">No free worker with this skill</small>'):'')+(j.worker?'<button type="button" class="secondary" data-take-off="'+j.id+'">Take off</button>':'')+(j.origin==='MANUAL'?'<button type="button" class="secondary" data-cancel-job="'+j.id+'">Cancel</button>':'')+(j.effect==='COUNT'?'<button type="button" class="secondary" data-start-count="'+esc(j.params.container)+'">Start stocktake</button>':'')+(j.subject?.kind==='container'?'<button type="button" class="text-button" data-select="'+esc(j.subject.id)+'">Open stillage</button>':'')+'</td></tr>';};
 const groups=[1,2,3,4,5,6,7,8].map(p=>{const ts=tasks.filter(t=>t.priority===p),js=jobs.filter(j=>j.priority===p);if(!ts.length&&!js.length)return '';return '<tr class="group"><td colspan="6">P'+p+' \u2013 '+esc(labels[p]??'')+'</td></tr>'+ts.map(taskRow).join('')+js.map(jobRow).join('');}).join('');
 const recent=(state.recentJobs??[]).filter(j=>j.yard===yard.id).slice(-8).reverse();
 return '<section class="panel job-board"><div class="row"><h2>Job board</h2><span class="badge">'+open+' open \u00b7 '+working+' in progress'+(blocked?' \u00b7 '+blocked+' blocked':'')+'</span></div>'+(groups?'<div class="table-scroll" data-keep-scroll="job-board"><table><thead><tr><th>Priority</th><th>Job</th><th>Where</th><th>Who</th><th>Progress</th><th>Actions</th></tr></thead><tbody>'+groups+'</tbody></table></div>':'<p class="muted">Nothing waiting. Automatic workers rotate through routine yard, equipment, safety, maintenance and improvement work (demo timers; routine work is never recorded as done work).</p>')+(recent.length?'<p class="muted recent-jobs"><strong>Recently done:</strong> '+recent.map(j=>esc(j.title)+' \u2013 '+esc(j.workerName??'engine')+' \u2013 '+when(j.completedAt)+(j.result?' \u2013 '+esc(j.result):'')).join(' | ')+'</p>':'')+'</section>';
}
function addJobPanel(yard,crew){
 const cat=(state.skillCatalogue??[]),category=cat.some(s=>s.code===jobDraft.category)?jobDraft.category:(cat[0]?.code??'YARD'),vocab=cat.find(s=>s.code===category)?.vocabulary??[],forklifts=state.resources.filter(r=>r.type==='FORKLIFT'&&r.location===yard.id&&Number.isFinite(r.x));
 const point=jobDraft.where?.kind==='point'?'Point set: '+(jobDraft.where.x/1000).toFixed(1)+', '+(jobDraft.where.y/1000).toFixed(1)+' m':'Click a spot on the plan';
 return '<section class="panel add-job"><h2>Add a job</h2><form id="create-job" class="inline-form"><label>Category<select name="category">'+cat.map(s=>'<option value="'+s.code+'" '+(s.code===category?'selected':'')+'>'+esc(s.label)+'</option>').join('')+'</select></label><label>Job<select name="title" data-vocabulary>'+vocab.map(v=>'<option value="'+esc(v)+'" '+(jobDraft.title===v?'selected':'')+'>'+esc(v)+'</option>').join('')+'<option value="OTHER" '+(jobDraft.title==='OTHER'?'selected':'')+'>Other\u2026</option></select></label><label class="custom-title" '+(jobDraft.title==='OTHER'?'':'hidden')+'>Describe it<input name="custom" maxlength="120" value="'+esc(jobDraft.custom??'')+'"></label><label>Where<select name="where">'+[['here','Where the worker stands'],['loading','Loading zone'],['gate','Gate']].map(([v,l])=>'<option value="'+v+'" '+(jobDraft.whereKey===v?'selected':'')+'>'+l+'</option>').join('')+forklifts.map(f=>'<option value="forklift:'+f.id+'" '+(jobDraft.whereKey==='forklift:'+f.id?'selected':'')+'>Beside '+esc(f.name)+'</option>').join('')+(selected&&state.containers.some(c=>c.id===selected&&c.location===yard.id)?'<option value="container:'+selected+'" '+(jobDraft.whereKey==='container:'+selected?'selected':'')+'>Beside '+esc(name(selected))+'</option>':'')+'<option value="plan" '+(jobDraft.whereKey==='plan'?'selected':'')+'>'+point+'</option></select></label><label>Priority<select name="priority">'+[1,2,3,4,5,6,7,8].map(p=>'<option value="'+p+'" '+((jobDraft.priority??cat.find(s=>s.code===category)?.priority)===p?'selected':'')+'>P'+p+' '+esc(state.ladder?.[yard.id]?.[p-1]?.label??'')+'</option>').join('')+'</select></label><label>Takes (s)<input type="number" name="seconds" value="'+(jobDraft.seconds??20)+'" min="1" max="600"></label><label>Worker<select name="worker"><option value="">Auto-assign from the board</option>'+crew.filter(w=>!w.task&&!w.mountedOn).map(w=>'<option value="'+w.id+'" '+(jobDraft.worker===w.id?'selected':'')+'>'+esc(w.name)+'</option>').join('')+'</select></label><button>Add to board</button></form><p class="muted">Custom jobs are recorded work with a demo timer; nothing in the yard changes when they finish.</p></section>';
}
function bindWorkersPage(){
 document.querySelectorAll('[data-crew-filter]').forEach(b=>b.onclick=()=>{crewFilter=b.dataset.crewFilter;render();});
 document.querySelectorAll('[data-row-open]').forEach(b=>b.onclick=()=>{const id=b.dataset.rowOpen;if(openRows.has(id))openRows.delete(id);else openRows.add(id);render();});
 document.querySelectorAll('[data-skills-open]').forEach(b=>b.onclick=()=>{const id=b.dataset.skillsOpen;if(skillsOpen.has(id))skillsOpen.delete(id);else{skillsOpen.add(id);openRows.add(id);}render();});
 document.querySelectorAll('[data-move-target]').forEach(s=>s.onchange=()=>moveTarget.set(s.dataset.moveTarget,s.value));document.querySelectorAll('[data-mount-select]').forEach(s=>s.onchange=()=>mountChoice.set(s.dataset.mountSelect,s.value));document.querySelectorAll('[data-allocate-select]').forEach(s=>s.onchange=()=>allocateChoice.set(s.dataset.allocateSelect,s.value));document.querySelectorAll('[data-give-worker]').forEach(s=>s.onchange=()=>giveWorker.set(s.dataset.giveWorker,s.value));
 document.querySelectorAll('[data-skill]').forEach(b=>b.onclick=async()=>{const on=b.getAttribute('aria-pressed')!=='true';b.classList.toggle('on',on);b.classList.toggle('off',!on);b.setAttribute('aria-pressed',String(on));try{await command('workerSkills',{id:b.dataset.workerId,skills:{[b.dataset.skill]:on}});await refresh(true);}catch(e){notify(e.message);}});
 action('[data-next-job]',e=>command('nextJob',{id:e.dataset.nextJob}));
 action('[data-allocate]',e=>{const id=e.dataset.allocate,job=document.querySelector('[data-allocate-select="'+id+'"]')?.value??allocateChoice.get(id);if(!job)throw new Error('Choose a job first.');return command('assignJob',{id:job,worker:id});});
 action('[data-give-job]',e=>{const job=e.dataset.giveJob,worker=document.querySelector('[data-give-worker="'+job+'"]')?.value??giveWorker.get(job);if(!worker)throw new Error('Choose a worker first.');return command('assignJob',{id:job,worker});});
 action('[data-take-off]',e=>command('takeOffJob',{id:e.dataset.takeOff}));action('[data-cancel-job]',e=>command('cancelJob',{id:e.dataset.cancelJob,reason:'Cancelled by the yard office'}));
 action('[data-jobs-mode]',e=>{const k=e.dataset.jobsMode,cfg=state.config??{};if(k==='resume')return command('jobsMode',{jobs:true});return command('jobsMode',{[k]:cfg[k]===false});});
 action('[data-allocate-all]',()=>command('nextJob',{yard:state.yards[0].id}).then(r=>notify(r.message)));
 action('[data-all-auto]',async()=>{for(const w of state.resources.filter(r=>r.type==='WORKER'&&r.location===state.yards[0].id&&!r.mountedOn&&!r.task&&(r.workerMode==='HOLD'||r.workerMode==='MOVING')))await command('workerCommand',{id:w.id,order:'AUTO'});});
 action('[data-hold-all]',async()=>{for(const w of state.resources.filter(r=>r.type==='WORKER'&&r.location===state.yards[0].id&&!r.mountedOn&&!r.task&&r.workerMode!=='HOLD'))await command('workerCommand',{id:w.id,order:'HOLD'});});
 action('[data-start-count]',e=>command('count',{scope:e.dataset.startCount}));
 const form=document.querySelector('#create-job');if(form){const cat=form.elements.namedItem('category'),title=form.elements.namedItem('title'),where=form.elements.namedItem('where');cat.onchange=()=>{jobDraft.category=cat.value;jobDraft.title=undefined;const vocab=(state.skillCatalogue??[]).find(s=>s.code===cat.value)?.vocabulary??[];title.innerHTML=vocab.map(v=>'<option value="'+esc(v)+'">'+esc(v)+'</option>').join('')+'<option value="OTHER">Other\u2026</option>';form.elements.namedItem('priority').value=String((state.skillCatalogue??[]).find(s=>s.code===cat.value)?.priority??7);};title.onchange=()=>{jobDraft.title=title.value;form.querySelector('.custom-title').hidden=title.value!=='OTHER';};where.onchange=()=>{jobDraft.whereKey=where.value;if(where.value==='plan'&&jobDraft.where?.kind!=='point'){workerMoveMode='JOB_TARGET';returnView='WORKERS';view='HOME';render();notify('Click a spot on the yard plan for this job. Esc cancels.');document.querySelector('.scene')?.scrollIntoView({block:'start'});}};form.querySelectorAll('input,select').forEach(el=>el.addEventListener('change',()=>{if(el.name==='custom')jobDraft.custom=el.value;if(el.name==='seconds')jobDraft.seconds=Number(el.value);if(el.name==='priority')jobDraft.priority=Number(el.value);if(el.name==='worker')jobDraft.worker=el.value;}));
  bind('create-job','createJob',d=>{const w=d.where==='plan'?(jobDraft.where?.kind==='point'?jobDraft.where:null):d.where==='here'||d.where==='loading'||d.where==='gate'?{kind:d.where}:{kind:d.where.split(':')[0],id:d.where.split(':')[1]};if(!w)throw new Error('Click a spot on the plan first.');return {yard:state.yards[0].id,category:d.category,title:d.title==='OTHER'?d.custom:d.title,where:w,priority:Number(d.priority),seconds:Number(d.seconds),worker:d.worker||undefined};},()=>{jobDraft={};});}
}
function equipmentView(){const yard=state.yards[0],machines=state.resources.filter(r=>r.type!=='WORKER');return '<section class="panel"><div class="row"><h2>Equipment</h2><span class="badge">'+machines.length+' machines · '+state.trucks.length+' trucks</span></div>'+fleetColumn(yard)+(machines.length?crewTable(machines):'<p class="muted">No handling equipment yet. Add forklifts for the yard; sites get cranes from the resources form on the Yard page.</p>')+'<p class="muted">Trucks are managed on their own pages: Truck 12.5 tonne and Truck 2 tonne.</p></section>';}
function materialsView(){return componentsPanel()+intakePanel();}
function planTools(){return '<div class="plan-tools"><button type="button" class="secondary" data-plan="zoom:1.25" title="Zoom in">+</button><span id="zoom-level">'+Math.round(planView.zoom*100)+'%</span><button type="button" class="secondary" data-plan="zoom:0.8" title="Zoom out">&minus;</button><button type="button" class="secondary" data-plan="rotate:-45" title="Rotate left">&#8634; Rotate</button><button type="button" class="secondary" data-plan="rotate:45" title="Rotate right">Rotate &#8635;</button><button type="button" class="secondary '+(planView.tilt?'current':'')+'" data-plan="tilt">'+(planView.tilt?'3D view':'Plan view')+'</button><button type="button" class="secondary" data-plan="reset">Reset view</button><span class="muted">Scroll to zoom &middot; drag empty ground to pan &middot; hover a stillage for its contents</span></div>';}
function homeView(){const yard=state.yards[0];if(!yard)return overviewView();const workers=state.resources.filter(r=>r.type==='WORKER'&&r.location===yard.id).length;return '<div class="home-grid"><div class="home-main"><section class="panel scene"><div class="row"><h2><span class="section-kicker">YARD</span>'+esc(yard.name)+'</h2><span>'+dims(yard)+'</span></div>'+planTools()+yardSVG(yard,plannedContainers(),state.tasks,selected,state.trucks,state.resources,selectedWorker,{balances:state.balances,products:state.products,view:planView,planned:layoutDraft?new Set(Object.keys(layoutDraft.moves)):null})+'<div class="scene-caption"><div class="map-legend"><span><i class="legend-dot stillage"></i>Stillages</span><span><i class="legend-dot cage"></i>Small-parts cages</span><span><i class="legend-dot loading"></i>Loading zone</span></div><span>'+(workerMoveMode==='JOB_TARGET'?'Click the plan to set the job location &middot; Esc cancels':layoutDraft?'Drag a stillage to a new spot &middot; drop it onto another stillage to stack it &middot; press R while dragging to turn it':workers+' workers on the yard &middot; left-click a worker to select &middot; right-click ground to move')+'</span></div>'+(!layoutDraft&&account.permissions.includes('operations.manage')?'<div class="actions"><button id="planner-start">Plan a new layout</button></div>':'')+'</section>'+(layoutDraft?plannerPanel(yard):workerPanel(yard))+layoutsPanel()+(selected&&state.containers.some(c=>c.id===selected&&c.location===yard.id)?detail():'')+'</div><aside class="home-side"><section class="panel"><h2>Fleet</h2>'+fleetColumn(yard)+'</section></aside></div>'+stockpilePanel();}
function overviewView(){
 const ops=account.permissions.includes('operations.manage'),yard=state.yards[0],yardIds=new Set(state.yards.map(y=>y.id));
 const workers=state.resources.filter(r=>r.type==='WORKER'),forklifts=state.resources.filter(r=>r.type==='FORKLIFT'),cranes=state.resources.filter(r=>r.type==='CRANE'),machines=ops?forklifts:cranes;
 const tasked=workers.filter(r=>!idleWorker(r)),idle=workers.filter(idleWorker),inYard=workers.filter(r=>yardIds.has(r.location)).length,hold=idle.filter(r=>r.workerMode==='HOLD').length,free=machines.filter(idleForklift).length,driving=workers.filter(r=>r.mountedOn).length;
 const tile=(value,label,sub,title)=>'<div title="'+esc(title)+'"><strong>'+value.toLocaleString()+'</strong><span>'+label+(sub?'<small>'+sub+'</small>':'')+'<span class="sr-only">. '+esc(title)+'</span></span></div>';
 const head=(label,note,viewId,button)=>'<div class="metrics-head"><div class="eyebrow">'+label+(note?' &middot; '+note:'')+'</div><button type="button" class="text-button" data-view="'+viewId+'">'+button+' &rarr;</button></div>';
 const crewRow=head('CREW &amp; MACHINES','','WORKERS','Open workers')+'<div class="metrics">'+tile(workers.length,'Workers',ops?inYard+' in the yard &middot; '+(workers.length-inYard)+' on sites':'on your sites','Everyone on the books in your scope: yard crew plus site crews')+tile(tasked.length,'Workers tasked',[workers.filter(r=>r.task).length+' on movements',driving?driving+' driving':''].filter(Boolean).join(' &middot; '),'On a stock movement, driving or walking to a forklift, or walking on orders')+tile(idle.length,'Workers idle',hold?hold+' on hold':'','Standing by: no movement, not on or heading to a forklift, not walking')+tile(machines.length,ops?'Forklifts':'Site cranes',[free+' free',ops&&cranes.length?cranes.length+' site cranes':''].filter(Boolean).join(' &middot; '),'Free = nobody on it, no job, no load, not reserved by a worker walking to it')+'</div>';
 const truckRow=(label,match,viewId,cls)=>{const fleet=state.trucks.filter(match),by=s=>fleet.filter(t=>truckStage(t,state)===s),sch=by('SCHEDULED'),ld=by('LOADING'),un=by('UNLOADING'),done=by('COMPLETE'),runs=state.runsToday?.[cls]??0,road=sch.filter(t=>t.status==='IN_TRANSIT').length,ready=ld.filter(t=>t.deckArea>0&&t.tasksTo===0).length,away=un.filter(t=>t.status==='IN_TRANSIT').length;return head(label,fleet.length?fleet.length+(ops?' in the fleet':' on your runs'):(ops?'none yet':'none on your runs'),viewId,fleet.length||!ops?'Open trucks':'Add one')+'<div class="metrics">'+tile(sch.length,'Scheduled',road?road+' on the road, empty':'','Booked for a run, nothing on the deck yet, no forklift has taken the job')+tile(ld.length,'Loading',ready?ready+' loaded, ready to go':'','A forklift is loading it, or it is loaded and waiting to leave')+tile(un.length,'Unloading',away?away+' on the road':'','At the site with the load on, being unloaded, or on the way there loaded')+tile(done.length,'Complete',[ops?done.filter(t=>t.status==='AT_YARD').length+' at the yard':'',runs?runs+' run'+(runs===1?'':'s')+' done today':''].filter(Boolean).join(' &middot; '),'Empty and free for the next run. Runs done today = loaded legs finished today, out to a site or back from one; a delivery that brings returns home counts as two')+'</div>';};
 const waiting=(state.loadLists??[]).filter(l=>!l.cancelled&&!l.truck&&l.status==='OPEN').length;
 return crewRow+truckRow('12.5 TONNE TRUCKS',heavyTruck,'TRUCK12','heavy')+truckRow('2 TONNE TRUCKS',t=>!heavyTruck(t),'TRUCK2','light')+'<p class="muted overview-legend">Scheduled = booked, nothing loaded &middot; Loading = a forklift is on it, or it is loaded and waiting to leave &middot; Unloading = load on: on the road, or arrived and being emptied at the site or back at the yard &middot; Complete = empty and free for the next run</p>'+(waiting?'<p class="muted overview-note">'+waiting+' yard list'+(waiting===1?'':'s')+' waiting for a truck &middot; <button type="button" class="text-button" data-view="SITES">Open yard lists &rarr;</button></p>':'')+'<div class="overview-grid">'+yardStockPanel(ops,yard)+sitePanel(ops)+'</div>';
}
const mergeBlocks=list=>{const rows=new Map();let pieces=0,reserved=0,unserviceable=0,containers=0;for(const b of list){if(!b)continue;pieces+=b.pieces;reserved+=b.reserved;unserviceable+=b.unserviceable;containers+=b.containers;for(const r of b.rows){const m=rows.get(r.product)??{...r,quantity:0,reserved:0,unserviceable:0,free:0,containers:0};m.quantity+=r.quantity;m.reserved+=r.reserved;m.unserviceable+=r.unserviceable;m.free+=r.free;m.containers+=r.containers;rows.set(r.product,m);}}return {pieces,reserved,unserviceable,containers,rows:[...rows.values()].sort((a,b)=>a.name.localeCompare(b.name))};};
function yardStockPanel(ops,yard){
 const block=ops?(yard?state.stock?.[yard.id]:null):mergeBlocks(state.sites.map(s=>state.stock?.[s.id])),rows=(block?.rows??[]).filter(r=>r.quantity>0),q=overviewSearch.trim().toLowerCase(),title=ops?'Stock in yard':'Stock on your sites',col=ops?'In yard':'On your sites';
 const body=ops&&!yard?'<p class="muted">Draw your yard first.</p><div class="actions"><button type="button" class="secondary" data-view="YARD">Open yard plan</button></div>'
  :!rows.length?'<p class="muted">'+(ops?'Nothing in the yard yet. Add stock from the Home stockpile.':'Nothing on your sites yet.')+'</p>'
  :'<input type="search" class="grid-search" id="overview-search" data-live-search placeholder="Find a material\u2026" value="'+esc(overviewSearch)+'" aria-label="Search '+title+'"><div class="table-scroll" data-keep-scroll="yard-stock"><table aria-label="'+title+'"><thead><tr><th>Material</th><th class="num">'+col+'</th><th class="num">Reserved</th><th class="num">Free to load</th></tr></thead><tbody>'+rows.map(r=>{const hay=(r.name+' '+(r.category??'')).toLowerCase();return '<tr data-yard-row data-hay="'+esc(hay)+'" '+(q&&!hay.includes(q)?'hidden':'')+'><td><strong>'+esc(r.name)+'</strong><small>'+esc(r.category??'')+'</small></td><td class="num"><strong>'+r.quantity.toLocaleString()+'</strong>'+(r.unserviceable?'<small>'+r.unserviceable.toLocaleString()+' damaged / quarantined</small>':'')+'</td><td class="num">'+r.reserved.toLocaleString()+'</td><td class="num">'+r.free.toLocaleString()+'</td></tr>';}).join('')+'</tbody></table></div><p class="muted overview-footnote">Reserved and free count this location only and leave out damaged or quarantined stock. The Stock page shows company-wide figures.</p><div class="actions"><a class="button-link" href="/api/export?kind=register">Export register CSV</a><button type="button" class="secondary" data-view="STOCK">Open stock</button></div>';
 return '<section class="panel yard-stock"><div class="row"><h2>'+title+'</h2><span class="badge">'+(block?.pieces??0).toLocaleString()+' pieces &middot; '+(block?.containers??0)+' stillages / cages</span></div>'+body+'</section>';
}
const siteTrucks=s=>{const here=t=>t.status!=='IN_TRANSIT'&&t.at===s.id,coming=t=>t.status==='IN_TRANSIT'&&t.destination===s.id,booked=t=>t.status!=='IN_TRANSIT'&&t.at!==s.id&&t.destination===s.id&&['SCHEDULED','LOADING'].includes(truckStage(t,state));return {here,coming,booked,list:state.trucks.filter(t=>here(t)||coming(t)||booked(t))};};
function sitePanel(ops){
 const active=state.sites.filter(s=>s.status==='ACTIVE').sort((a,b)=>a.name.localeCompare(b.name,undefined,{numeric:true})),archived=state.sites.length-active.length;
 if(pinnedSite&&!active.some(s=>s.id===pinnedSite))pinnedSite=null;if(heldSite&&!active.some(s=>s.id===heldSite))heldSite=null;
 const shown=active.find(s=>s.id===(pinnedSite??heldSite)),searchable=active.length>8,q=searchable?siteSearch.trim().toLowerCase():'';
 const rows=active.map(s=>{const stock=state.stock?.[s.id],tr=siteTrucks(s),pinned=s.id===pinnedSite,hay=(s.name+' '+s.address+' '+(s.client??'')).toLowerCase();return '<li class="site-row'+(pinned?' pinned':s.id===heldSite?' held':'')+'" data-site="'+s.id+'" data-focus-scope="site:'+s.id+'" data-hay="'+esc(hay)+'" '+(q&&!hay.includes(q)?'hidden':'')+'><button type="button" class="site-toggle" data-site-pin="'+s.id+'" aria-expanded="'+pinned+'" aria-controls="site-card-slot">&#9873; '+esc(s.name)+'</button><span class="site-meta">'+(stock?.pieces??0).toLocaleString()+' pcs'+(tr.list.length?' <span class="badge '+(tr.list.some(tr.here)?'available':'busy')+'">'+tr.list.length+' truck'+(tr.list.length===1?'':'s')+'</span>':'')+'</span></li>';}).join('');
 return '<section class="panel site-panel" id="site-panel"><div class="row"><h2>'+(ops?'Sites':'Your sites')+'</h2><span class="badge">'+active.length+' active</span></div><p class="muted site-hint">Hover a site for its address, client details and what is on site. Click or press Enter to keep the card open; &times; or Esc closes it.</p>'+(active.length?(searchable?'<input type="search" class="grid-search" id="site-search" data-live-search placeholder="Find a site\u2026" value="'+esc(siteSearch)+'" aria-label="Search sites">':'')+'<ul class="site-list" data-keep-scroll="site-list">'+rows+'</ul>':'<p class="muted">'+(ops?'No sites yet.':'No sites are assigned to you yet.')+'</p>'+(ops?'<div class="actions"><button type="button" class="secondary" data-view="SITES">Create a site</button></div>':''))+'<div class="site-card-slot" id="site-card-slot">'+(shown?siteCard(shown,ops):'')+'</div>'+(archived?'<p class="muted site-footer">'+archived+' archived site'+(archived===1?'':'s')+' on the Client sites page</p>':'')+'</section>';
}
function siteCard(s,ops){
 const stock=state.stock?.[s.id],tr=siteTrucks(s),rows=(stock?.rows??[]).filter(r=>r.quantity>0),last=s.lastDeliveryAt?{completedAt:s.lastDeliveryAt}:null;
 const word=t=>tr.coming(t)?(t.deckArea>0?'on the way here, loaded':'on the way here, empty'):tr.here(t)?({UNLOADING:'unloading here',LOADING:'loading returns',SCHEDULED:'booked here',COMPLETE:'free on site'})[truckStage(t,state)]:({LOADING:'loading at the yard',SCHEDULED:'booked at the yard'})[truckStage(t,state)];
 const contact=(s.client||s.contact?'<p class="site-card-line"><strong>'+esc(s.client??'')+'</strong>'+(s.contact?(s.client?' &middot; ':'')+esc(s.contact):'')+'</p>':'')
  +(s.email||s.phone?'<p class="site-card-line">'+(s.email?'<a href="mailto:'+esc(s.email)+'">'+esc(s.email)+'</a>':'')+(s.phone?(s.email?' &middot; ':'')+'<a href="tel:'+esc(String(s.phone).replace(/\s+/g,''))+'">'+esc(s.phone)+'</a>':'')+'</p>':'')
  +(!s.client&&!s.contact&&!s.email&&!s.phone?'<p class="site-card-line muted">No client details yet'+(ops?' &middot; add them on the Client sites page':'')+'</p>':'');
 const table=rows.length
  ?'<div class="table-scroll"><table><thead><tr><th>Material</th><th class="num">On site</th><th class="num">Stillages / cages</th></tr></thead><tbody>'+rows.map(r=>'<tr><td>'+esc(r.name)+'<small>'+esc(r.category??'')+'</small></td><td class="num"><strong>'+r.quantity.toLocaleString()+'</strong>'+(r.reserved?'<small>'+r.reserved+' reserved for return</small>':'')+(r.unserviceable?'<small>'+r.unserviceable+' damaged / quarantined</small>':'')+'</td><td class="num">'+r.containers+'</td></tr>').join('')+'</tbody></table></div><p class="site-card-line muted">'+stock.pieces.toLocaleString()+' pieces in '+stock.containers+' stillages / cages'+(last?' &middot; last delivery '+when(last.completedAt):'')+'</p>'
  :'<p class="site-card-line muted">Nothing on site'+(stock?.containers?' &middot; '+stock.containers+' empty stillages / cages to bring back':'')+(last?' &middot; last delivery '+when(last.completedAt):'')+'</p>';
 return '<div class="site-card" role="group" aria-label="'+esc(s.name)+' details" data-focus-scope="card:'+s.id+'"><button type="button" class="site-card-close secondary" data-site-close aria-label="Close site card">&times;</button><div class="row"><strong>'+esc(s.name)+'</strong><span class="badge available">ACTIVE</span></div><p class="site-card-line">'+esc(s.address)+'</p>'+contact+'<p class="site-card-line muted">Supervisor: '+esc(s.supervisorName??'Not assigned')+(tr.list.length?' &middot; '+tr.list.map(t=>esc(t.name)+' '+word(t)).join(', '):'')+'</p><h3>Materials on site</h3>'+table+'<div class="actions"><button type="button" class="secondary" data-view="SITES">Open site</button></div></div>';
}
function bindOverview(){
 const live=(sel,set,rows)=>{const input=document.querySelector(sel);if(!input)return;input.oninput=()=>{set(input.value);const q=input.value.trim().toLowerCase();document.querySelectorAll(rows).forEach(row=>row.hidden=!!q&&!row.dataset.hay.includes(q));};};
 live('#overview-search',v=>overviewSearch=v,'[data-yard-row]');live('#site-search',v=>siteSearch=v,'[data-site]');
 if(!document.querySelector('#site-panel'))return;
 const showSite=()=>{const ops=account.permissions.includes('operations.manage'),shown=state.sites.find(s=>s.id===(pinnedSite??heldSite)&&s.status==='ACTIVE');document.querySelectorAll('[data-site]').forEach(li=>{li.classList.toggle('pinned',li.dataset.site===pinnedSite);li.classList.toggle('held',!pinnedSite&&li.dataset.site===heldSite);li.querySelector('[data-site-pin]')?.setAttribute('aria-expanded',String(li.dataset.site===pinnedSite));});const slot=document.querySelector('#site-card-slot');if(!slot)return;slot.innerHTML=shown?siteCard(shown,ops):'';slot.querySelector('[data-site-close]')?.addEventListener('click',()=>{pinnedSite=null;heldSite=null;showSite();});slot.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;selected=null;pinnedSite=null;heldSite=null;if(!['YARD','HOME'].includes(view)){layoutDraft=null;layoutCheck=null;}render();});};
 document.querySelectorAll('[data-site]').forEach(row=>row.onpointerenter=e=>{const id=row.dataset.site;if(e.pointerType==='touch'||heldSite===id)return;heldSite=id;if(!pinnedSite)showSite();});
 document.querySelectorAll('[data-site-pin]').forEach(b=>b.onclick=()=>{const id=b.dataset.sitePin;pinnedSite=pinnedSite===id?null:id;showSite();});
 document.querySelector('[data-site-close]')?.addEventListener('click',()=>{pinnedSite=null;heldSite=null;showSite();});
 app.onpointerover=e=>{if(e.pointerType==='touch'||!heldSite||e.target.closest('#site-panel'))return;heldSite=null;if(!pinnedSite)showSite();};
 document.onkeydown=e=>{if(e.key==='Escape'&&(pinnedSite||heldSite)&&!e.target.matches?.('input,select,textarea')){pinnedSite=null;heldSite=null;showSite();}};
}
function parkingForm(yard){if(!yard)return '';const p=yard.parking;const metres=(key,label,value)=>'<label>'+label+'<input type="number" name="'+key+'" value="'+value+'" min="'+(key==='clearance'?0:1)+'" max="'+(key==='vehicleWidth'?5:key==='clearance'?10:30)+'" step="0.01" required></label>';return form('parking','Truck parking apron - dimensions', '<p>Separate apron beside the storage boundary. Confirm the available land and enter the overall vehicle size, including cab. Clearance applies on all four sides.</p>'+(!p?'<p class="notice">Preview uses your 6 m deck plus an assumed 3 m cab: 9 x 2.1 m truck with 0.5 m clearance. Replace these with your measurements.</p>':'')+select('side','Side of yard',[{id:p?.side??'RIGHT',name:p?.side==='LEFT'?'Left':'Right'},{id:p?.side==='LEFT'?'RIGHT':'LEFT',name:p?.side==='LEFT'?'Right':'Left'}])+metres('vehicleLength','Overall truck length (m)',(p?.vehicleLength??9000)/1000)+metres('vehicleWidth','Overall truck width (m)',(p?.vehicleWidth??2100)/1000)+metres('clearance','Clearance on each side (m)',(p?.clearance??500)/1000),'Save parking dimensions');
}

function truckRemoveButton(t){if(!account.permissions.includes('operations.manage'))return '';const busy=t.status==='IN_TRANSIT'||state.containers.some(c=>c.location===t.id)||state.tasks.some(x=>x.to===t.id||x.from===t.id)||(state.loadLists??[]).some(l=>l.truck===t.id&&!l.cancelled&&!l.delivery);return `<button type="button" class="secondary" data-retire="${t.id}" data-retire-label="truck ${esc(t.name)}" ${busy?'disabled':''}>Remove truck</button>`;}
function emptyState(type,title,body){return `<section class="panel empty-state">${icon(type)}<h2>${title}</h2><p>${body}</p></section>`;}
function containerCards(location){return `<div class="container-list">${state.containers.filter(c=>!location||c.location===location).map(c=>`<button class="container-card" data-select="${c.id}" draggable="true">${packArt(c.type)}<strong>${esc(c.name)}</strong><small>${esc(c.type)} · ${state.balances.filter(l=>l.container===c.id).reduce((s,l)=>s+l.quantity,0)} pieces${c.support?' · stacked':''}</small>${(()=>{const lines=state.balances.filter(l=>l.container===c.id&&l.quantity>0);return lines.length?`<small class="card-contents">${lines.slice(0,2).map(l=>`${l.quantity} × ${esc(name(l.product_id))}`).join('<br>')}${lines.length>2?`<br>+${lines.length-2} more`:''}</small>`:'<small class="card-contents muted">Empty</small>';})()}<small class="condition-label ${c.condition==='SERVICEABLE'?'good':'attention'}">${esc(c.condition)}</small></button>`).join('')||'<p class="muted">No stillages or cages here yet.</p>'}</div>`;}
function yardView(){const yard=state.yards[0];const workers=state.resources.filter(r=>r.type==='WORKER'&&r.location===yard?.id).length;return `<div class="metrics"><div><strong>${state.containers.filter(c=>c.location===yard?.id).length}</strong><span>Stillages & cages in yard</span></div><div><strong>${workers}</strong><span>Yard workers</span></div><div><strong>${state.resources.filter(r=>r.type==='FORKLIFT'&&r.location===yard?.id).length}</strong><span>Forklifts</span></div><div><strong>${state.sites.filter(s=>s.status==='ACTIVE').length}</strong><span>Active sites</span></div></div>${yard&&account.permissions.includes('operations.manage')?`<section class="panel"><div class="row"><h2>Crew, equipment &amp; storage</h2><span class="muted">${esc(yard.name)}</span></div><div class="quick-grid">${quickRow('WORKER','worker',state.resources.filter(r=>r.type==='WORKER'&&r.location===yard.id).length,'Yard workers')}${quickRow('FORKLIFT','forklift',state.resources.filter(r=>r.type==='FORKLIFT'&&r.location===yard.id).length,'Forklifts')}${quickRow('TRUCK2','truck',state.trucks.filter(t=>t.yard===yard.id&&t.payload<10000000).length,'Trucks · 2 tonne')}${quickRow('TRUCK12','truck',state.trucks.filter(t=>t.yard===yard.id&&t.payload>=10000000).length,'Trucks · 12.5 tonne')}${quickRow('STILLAGE','stillage',state.containers.filter(c=>c.location===yard.id&&c.type==='STILLAGE').length,'Stillages in yard')}</div><p class="muted">Removing takes the most recently added idle one; select a worker, forklift, truck or stillage below to remove that specific one.</p></section>`:''}${yard?`<section class="panel scene"><div class="row"><h2><span class="section-kicker">LIVE YARD PLAN</span>${esc(yard.name)}</h2><span>${dims(yard)} · 1 m grid</span></div>${planTools()}${yardSVG(yard,plannedContainers(),state.tasks,selected,state.trucks,state.resources,selectedWorker,{balances:state.balances,products:state.products,view:planView,planned:layoutDraft?new Set(Object.keys(layoutDraft.moves)):null})}<div class="scene-caption"><div class="map-legend"><span><i class="legend-dot stillage"></i>Stillages</span><span><i class="legend-dot cage"></i>Small-parts cages</span><span><i class="legend-dot loading"></i>Loading zone</span></div><span>${layoutDraft?'Drag a stillage to a new spot &middot; drop it onto another stillage to stack it &middot; press R while dragging to turn it':'Left-click worker to select &middot; Right-click ground to move'}</span></div></section>${layoutDraft?plannerPanel(yard):workerPanel(yard)}${layoutsPanel()}${yardListsPanel(l=>['OPEN','PARTIAL','RESERVED','LOADED'].includes(l.status),false)}${containerCards(yard.id)}${selected&&state.containers.some(c=>c.id===selected&&c.location===yard.id)?detail():''}<div class="drop-zones">${state.trucks.filter(t=>t.at===yard.id&&t.status==='AT_YARD').map(t=>`<div class="drop-zone" data-drop="${t.id}"><strong>▰ ${esc(t.name)}</strong><span>Drop a stillage or cage to request loading</span>${truckRemoveButton(t)}</div>`).join('')}</div><div class="actions"><button class="secondary" id="edit-yard">Edit yard, fixtures &amp; dimensions</button>${!layoutDraft&&account.permissions.includes('operations.manage')?'<button id="planner-start">Plan a new layout</button>':''}</div>`:''}${(!yard||editingYard)&&!editingSite?builder():''}${account.permissions.includes('operations.manage')?parkingForm(yard)+resourceForm(yard)+containerForm(yard):''}`;}
const dims=loc=>{const pts=loc?.points??[];if(pts.length<3)return '';const xs=pts.map(p=>p.x),ys=pts.map(p=>p.y);let area=0;for(let i=0;i<pts.length;i++){const a=pts[i],b=pts[(i+1)%pts.length];area+=a.x*b.y-b.x*a.y;}return ((Math.max(...xs)-Math.min(...xs))/1000).toFixed(1)+' × '+((Math.max(...ys)-Math.min(...ys))/1000).toFixed(1)+' m · '+(Math.abs(area)/2e6).toFixed(1)+' m²';};
const rectSegments=loc=>{const pts=loc.points,xs=pts.map(p=>p.x),ys=pts.map(p=>p.y),w=Math.max(...xs)-Math.min(...xs),h=Math.max(...ys)-Math.min(...ys);return [{direction:'RIGHT',length:w},{direction:'DOWN',length:h},{direction:'LEFT',length:w}];};
function builder(){const preview=outline(segments,closed);const target=editingSite??editingYard;const what=editingSite?'site':'yard';return `<section class="panel" id="builder"><h2>${editingSite?'Edit site boundary':editingYard?'Edit yard':'Draw your yard'}</h2><p>Each line starts where the last one ends. Enter its actual length in metres.${target?` You can resize at any time: stillages left outside the new boundary are moved to the nearest clear ground inside it, crew are re-seated, and the loading zone follows if it no longer fits.`:''}</p><div class="builder-grid"><div><form id="segment"><fieldset><legend>Direction</legend><div class="directions">${[['NW','↖'],['UP','↑'],['NE','↗'],['LEFT','←'],['RIGHT','→'],['SW','↙'],['DOWN','↓'],['SE','↘']].map(([d,s])=>`<label><input type="radio" name="direction" value="${d}" ${d==='RIGHT'?'checked':''}>${s} ${d}</label>`).join('')}</div></fieldset><label>Line length (m)<input type="number" name="metres" min="0.001" max="1000" step="0.001" value="20" required></label><button>Add segment</button></form><ol>${segments.map((s,i)=>`<li><select aria-label="Segment ${i+1} direction" data-segment-dir="${i}">${['RIGHT','LEFT','UP','DOWN','NE','SE','SW','NW'].map(d=>`<option ${s.direction===d?'selected':''}>${d}</option>`).join('')}</select><input aria-label="Segment ${i+1} length in metres" type="number" min="0.001" step="0.001" data-segment-length="${i}" value="${s.length/1000}"> m <button type="button" class="text-button" data-segment-remove="${i}" aria-label="Remove segment ${i+1}">&times; Remove</button></li>`).join('')}</ol><div class="actions"><button class="secondary" id="undo-segment">Undo last</button><button class="secondary" id="reset-segments">Reset</button><button class="secondary" id="close-yard">${closed?'Perimeter closed ✓':'Preview and close perimeter'}</button>${closed?`<button type="submit" form="${editingSite?'save-site':'save-yard'}">Save ${what} now</button>`:''}</div><p class="muted">${closed?`Perimeter closed. Press &ldquo;Save ${what} now&rdquo; to apply the new dimensions &mdash; the name, height, loading zone and gate below are saved with it.`:'Closing adds the displayed last-to-first boundary explicitly. Endpoints within 1 mm are treated as closed.'}</p><form id="${editingSite?'save-site':'save-yard'}">${text('name',editingSite?'Site name':'Yard name',target?.name??'Main yard')}${number('height','Maximum storage height (mm)',target?.height??10000,1)}<fieldset><legend>Loading zone &amp; gate</legend><p class="muted">Positions are the top-left corner in metres from the ${what} origin. Loading needs a clear 2 × 1.5 m footprint inside the boundary; truck loading routes start and end here.</p><div class="form-grid">${[['loadingX','Loading zone X (m)',target?.loading?.x],['loadingY','Loading zone Y (m)',target?.loading?.y],['gateX','Gate X (m)',target?.gate?.x],['gateY','Gate Y (m)',target?.gate?.y]].map(([k,l,v])=>`<label>${l}<input type="number" name="${k}" value="${(v??1000)/1000}" step="0.01" required></label>`).join('')}</div></fieldset>${editingSite?'':fixtureEditor()}${closed?'':`<p class="notice">Changing a line reopens the perimeter for review. Press &ldquo;Preview and close perimeter&rdquo; above &mdash; then Save ${what} becomes available.</p>`}<div class="actions"><button ${closed?'':'disabled'} title="${closed?'':'Preview and close the perimeter first'}">Save ${what}</button>${target?`<button type="button" class="secondary" id="cancel-builder">Cancel</button>`:''}</div></form></div><div>${yardSVG({name:'Boundary preview',points:preview.points,fixtures:editingSite?[]:(fixtureRows??[]),loading:editingSite?editingSite.loading:editingYard?.loading})}<p>${closed?'Closing edge confirmed.':'The last-to-first line is a closing preview only.'}</p></div></div></section>`;}
function resourceForm(location){if(!location)return '';return form('resources','Configure workers & equipment · DEMO ONLY',select('location','Location',[...state.yards,...state.sites.filter(s=>s.status==='ACTIVE')])+qty('workers',5)+number('machines','Forklifts (yard) / cranes (site)',1)+number('capacity','Machine capacity (grams)',1500000,1)+number('stepMs','Pickup / placement time (milliseconds)',700,100)+number('speed','Travel speed (mm per second)',4000,1)+number('craneWorkers','Workers required per crane task',1,1),'Save resources');}
function containerForm(location){if(!location)return '';return form('container','Add a stillage or small-parts cage',text('name','Stillage / cage label',`S-${String(state.containers.length+1).padStart(3,'0')}`)+select('location','Storage location',[...state.yards,...state.sites.filter(s=>s.status==='ACTIVE')])+select('type','Storage type',[{id:'STILLAGE',name:'Open stillage - scaffold tubes & ledgers'},{id:'CAGE',name:'Mesh cage - fittings & small items'},{id:'RACK',name:'Storage rack'},{id:'BUNDLE',name:'Strapped bundle'}])+`<div class="form-grid">${number('length','Frame length (mm)',2000,1)}${number('width','Frame width (mm)',1000,1)}${number('height','Frame height (mm)',1000,1)}${number('envelopeLength','Loaded length (mm)',2000,1)}${number('envelopeWidth','Loaded width (mm)',1000,1)}${number('tare','Frame tare (g) — DEMO',50000)}${number('x','X position (mm)',4000,-1000000)}${number('y','Y position (mm)',4000,-1000000)}</div><p class="muted">These suggested dimensions and weights are synthetic simulation values, not manufacturer ratings.</p>`,'Register stillage / cage');}
function componentsPanel(){const tabs=[{id:'ALL',name:'All components'},...account.systems.filter(s=>s.enabled)];const active=tabs.some(s=>s.id===componentTab)?componentTab:'ALL';const products=state.products.filter(p=>!p.retired&&(active==='ALL'||p.system===active));return `<section class="panel"><div class="row"><h2>Components</h2><span class="badge">${products.length} of ${state.products.filter(p=>!p.retired).length}</span></div><div class="subtabs" role="tablist">${tabs.map(s=>`<button type="button" class="secondary ${s.id===active?'current':''}" data-component-tab="${s.id}" role="tab" aria-selected="${s.id===active}">${esc(s.name)}</button>`).join('')}</div><div class="table-scroll"><table><thead><tr><th>Name</th><th>System</th><th>Category</th><th>Manufacturer / reference</th><th>Unit weight</th><th>Pack qty</th><th>Verification</th></tr></thead><tbody>${products.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(account.systems.find(s=>s.id===p.system)?.name??p.system)}</td><td>${esc(p.category)}</td><td>${esc(p.manufacturer)} · ${esc(p.reference)}</td><td>${p.unitWeight!==null?kg(p.unitWeight):'Unknown'}</td><td>${p.packQuantity??'—'}</td><td>${esc(p.verification)}</td></tr>`).join('')||'<tr><td colspan="7">No components in this system yet.</td></tr>'}</tbody></table></div></section>`;}
const when=iso=>{try{return new Date(iso).toLocaleString();}catch{return esc(iso);}};
const storageContainers=()=>state.containers.filter(c=>state.yards.some(y=>y.id===c.location)||state.sites.some(y=>y.id===c.location));
const enabledProducts=()=>state.products.filter(p=>!p.retired&&account.systems.some(s=>s.id===p.system&&s.enabled));
const demoPresent=()=>state.products.some(p=>p.verification==='DEMO ONLY'&&!p.retired);
const purgeButton=()=>demoPresent()&&account.permissions.includes('stock.adjust')?'<div class="notice">Demonstration data is present: '+state.products.filter(p=>p.verification==='DEMO ONLY'&&!p.retired).length+' synthetic product(s)'+((state.register??[]).some(r=>state.products.find(p=>p.id===r.product)?.verification==='DEMO ONLY')?' with stock on hand':'')+'. <button type="button" class="secondary" id="purge-demo">Remove all demonstration products and stock</button></div>':'';
function stockTabs(){const tabs=[['REGISTER','Materials register'],['ADDED','Added stock'],['REMOVED','Removed stock'],['CONTAINERS','Stillages & cages'],['COMPONENTS','Components']];return '<div class="subtabs" role="tablist">'+tabs.map(([id,label])=>'<button type="button" class="secondary '+(id===stockTab?'current':'')+'" data-stock-tab="'+id+'" role="tab" aria-selected="'+(id===stockTab)+'">'+label+'</button>').join('')+'</div>';}
function registerPanel(){const rows=state.register??[];return purgeButton()+'<section class="panel"><div class="row"><h2>Materials register</h2><a class="button-link" href="/api/export?kind=register">Export register CSV</a></div><p>Total stock the company owns right now, per product, across the yard, sites and trucks. This is the original list of stock plus everything added, minus everything removed.</p><div class="table-scroll"><table><thead><tr><th>Product</th><th>System</th><th>In yard</th><th>At sites</th><th>On trucks</th><th>Total</th><th>Reserved</th><th>Available</th></tr></thead><tbody>'+rows.map(r=>'<tr><td><strong>'+esc(r.name)+'</strong><small>'+esc(r.category??'')+'</small></td><td>'+esc(account.systems.find(s=>s.id===r.system)?.name??r.system??'')+'</td><td>'+r.yard+'</td><td>'+r.site+'</td><td>'+r.truck+'</td><td><strong>'+r.quantity+'</strong></td><td>'+r.reserved+'</td><td>'+r.available+'</td></tr>').join('')+(rows.length?'':'<tr><td colspan="8">No stock has been recorded yet. Record your original stock below.</td></tr>')+'</tbody></table></div></section>'+(account.permissions.includes('stock.adjust')?form('opening','Record original stock (opening balance)',select('container','Stillage / cage',storageContainers())+select('product','Product',enabledProducts())+qty()+text('reason','Reason','Original stock on hand'),'Record original stock'):'');}
function stockLogTable(rows,empty){return '<div class="table-scroll"><table><thead><tr><th>When</th><th>Product</th><th>Quantity</th><th>Stillage / cage</th><th>Location</th><th>Reason</th></tr></thead><tbody>'+rows.map(l=>'<tr><td>'+when(l.created_at)+'<small>'+esc(l.event.replaceAll('_',' '))+'</small></td><td>'+esc(name(l.product_id))+'</td><td><strong>'+l.quantity+'</strong></td><td>'+esc(name(l.container_id))+'</td><td>'+esc(name(l.destination??l.source))+'</td><td>'+esc(l.reason)+'</td></tr>').join('')+(rows.length?'':'<tr><td colspan="6">'+empty+'</td></tr>')+'</tbody></table></div>';}
function additionsPanel(){return '<section class="panel"><div class="row"><h2>Added stock</h2><a class="button-link" href="/api/export?kind=additions">Export additions CSV</a></div><p>Every purchase and original-stock receipt, newest first.</p>'+stockLogTable(state.additions??[],'Nothing has been added yet.')+'</section>'+(account.permissions.includes('stock.adjust')?form('purchase','Record a purchase',select('container','Receive into stillage / cage',storageContainers())+select('product','Product',enabledProducts())+qty()+'<label>Supplier (optional)<input name="supplier" maxlength="250"></label>'+text('reason','Reason / invoice reference','Purchased stock'),'Add purchased stock'):'');}
function removalsPanel(){return '<section class="panel"><div class="row"><h2>Removed stock</h2><a class="button-link" href="/api/export?kind=removals">Export removals CSV</a></div><p>Stock sold, scrapped or otherwise taken out of the company, newest first. Reserved, in-transit and counted stock cannot be removed.</p>'+stockLogTable(state.removals??[],'Nothing has been removed yet.')+'</section>'+(account.permissions.includes('stock.adjust')?form('remove-stock','Record a sale / removal',select('container','Remove from stillage / cage',storageContainers().filter(c=>state.balances.some(l=>l.container===c.id)))+select('product','Product',enabledProducts())+qty('quantity',10)+text('reason','Reason / sale reference','Sold to customer'),'Remove stock'):'');}
const listBadge=s=>({OPEN:'busy',PARTIAL:'busy',RESERVED:'available',LOADED:'available',IN_TRANSIT:'available',AT_SITE:'available',DELIVERED:'available',CANCELLED:''}[s]??'');
function loadListCard(l,controls){const ops=account.permissions.includes('operations.manage');const truckSelect=state.trucks.filter(t=>t.status==='AT_YARD'&&(!t.destination||t.destination===l.site));return '<section class="panel load-list" data-load-list="'+l.id+'"><div class="row"><h2>'+esc(l.name)+'</h2><span class="badge '+listBadge(l.status)+'">'+esc(l.status.replaceAll('_',' '))+(l.short&&!['OPEN','CANCELLED'].includes(l.status)?' · '+l.short+' short':'')+'</span></div><p>To <strong>'+esc(name(l.site))+'</strong>'+(l.truckName?' · truck <strong>'+esc(l.truckName)+'</strong>':'')+' · '+l.requested+' pieces requested · '+(l.delivery?l.lines.reduce((s,x)=>s+(x.sent??0),0)+' sent':l.loaded+' on truck')+' · '+l.delivered+' at site'+(l.departedAt?' · departed '+when(l.departedAt):'')+(l.notes?' · '+esc(l.notes):'')+'</p><div class="table-scroll"><table><thead><tr><th>Product</th><th>Requested</th><th>Reserved</th><th>'+(l.delivery?'Sent':'On truck')+'</th><th>At site</th><th>Line</th></tr></thead><tbody>'+l.lines.map(x=>'<tr><td>'+esc(x.name)+'</td><td>'+x.quantity+'</td><td>'+x.reserved+'</td><td>'+(l.delivery?(x.sent??0)+(x.sent?'':' <small>not sent</small>'):x.loaded)+'</td><td>'+x.delivered+'</td><td><span class="badge '+(x.status==='DELIVERED'?'available':x.status==='REQUESTED'?'busy':'')+'">'+esc(x.status.replaceAll('_',' '))+'</span>'+(x.lastReason&&x.status==='REQUESTED'?'<br><span class="error-text">'+esc(x.lastReason)+'</span>':'')+'</td></tr>').join('')+'</tbody></table></div>'+(controls&&!l.cancelled?'<div class="actions">'+(ops&&l.lines.some(x=>x.status==='REQUESTED')?'<form data-allocate-list="'+l.id+'" class="inline-form">'+(truckSelect.length?'<label>Loading truck<select name="truck" required>'+options(truckSelect)+'</select></label><button>Reserve packs &amp; load truck</button>':'<span class="muted">No truck at the yard for this site.</span>')+'</form>':'')+(!['DELIVERED'].includes(l.status)?'<button type="button" class="secondary" data-cancel-list="'+l.id+'">Cancel remaining lines</button>':'')+'</div>':'')+(l.cancelled&&l.cancelReason?'<p class="muted">Cancelled: '+esc(l.cancelReason)+'</p>':'')+'</section>';}
function loadListForm(){const products=enabledProducts(),sites=state.sites.filter(s=>s.status==='ACTIVE');if(!sites.length||!products.length)return '';const row=i=>'<div class="load-line"><label>Product<select name="product'+i+'"><option value="">— none —</option>'+options(products)+'</select></label><label>Quantity<input type="number" name="quantity'+i+'" min="0" step="1" value="0"></label></div>';return '<details class="panel" id="load-list-panel"><summary>Create a yard list (load list for one truck)</summary><form id="load-list"><p>List everything the yardsman must put on the truck for this site. The same list travels with the truck as the delivery docket. Each product once; leave unused lines at 0.</p>'+text('name','Yard list name','Yard list '+new Date().toISOString().slice(0,10))+select('site','Destination site',sites)+'<label>Notes<input name="notes" maxlength="250" value="Demonstration delivery"></label><div id="load-lines">'+[0,1,2,3].map(row).join('')+'</div><div class="actions"><button type="button" class="secondary" id="add-load-line">Add another line</button><button>Create yard list</button></div></form></details>';}
function yardListsPanel(filter,controls){const lists=(state.loadLists??[]).filter(filter);if(!lists.length)return '';return lists.map(l=>loadListCard(l,controls)).join('');}
function manifestPanel(delivery,title){const lists=delivery?.manifest??[];if(!lists.length)return '';return '<section class="panel"><div class="row"><h2>'+title+'</h2><span class="badge">'+esc(delivery.status)+'</span></div><p>'+esc(name(delivery.from))+' → '+esc(name(delivery.to))+' · '+delivery.containers.length+' stillages / cages · '+when(delivery.createdAt)+'</p>'+lists.map(l=>loadListCard(l,false)).join('')+'</section>';}
function stockView(){const total=state.stockTotal,reserved=state.reservedTotal;return `<div class="metrics"><div><strong>${total.toLocaleString()}</strong><span>Physical pieces in your scope</span></div><div><strong>${reserved}</strong><span>Reserved · included in physical stock</span></div><div><strong>${total-reserved}</strong><span>Unreserved pieces</span></div></div>${stockTabs()}${stockTab==='REGISTER'?registerPanel():stockTab==='ADDED'?additionsPanel():stockTab==='REMOVED'?removalsPanel():stockTab==='COMPONENTS'?componentsPanel():`<section class="panel"><div class="row"><h2>Stock by stillage & cage</h2><a class="button-link" href="/api/export?kind=stock">Export stock CSV</a></div><label>Search product or stillage / cage<input id="stock-search" type="search" placeholder="Ledger, S-001…"></label><div class="table-scroll"><table aria-label="Stock by stillage & cage"><thead><tr><th>Product</th><th>Stillage / cage / location</th><th>Physical</th><th>Reserved</th><th>Available</th><th>Condition</th></tr></thead><tbody>${state.balances.map(l=>`<tr data-stock-row><td>${esc(name(l.product_id))}</td><td><button class="text-button" data-select="${l.container}">${esc(name(l.container))}</button><small>${esc(name(l.location))}</small></td><td>${l.quantity}</td><td>${l.reserved}</td><td>${l.condition==='SERVICEABLE'?l.quantity-l.reserved:0}</td><td>${esc(l.condition)}</td></tr>`).join('')||'<tr><td colspan="6">No stock has been received.</td></tr>'}</tbody></table></div></section>${account.permissions.includes('operations.manage')?form('count','Start a stocktake',select('scope','Count scope',[...state.yards,...state.sites,...state.containers]),'Start count and lock scope'):''}${state.counts.map(c=>`<section class="panel"><h2>Stocktake · ${esc(c.name)} <span class="badge">${c.state}</span></h2>${c.state==='OPEN'?`<form data-count="${c.id}">${c.lines.map((l,i)=>number(`line${i}`,`${name(l.product_id)} in ${name(l.container)} · expected ${l.expected}`,l.observed??l.expected)).join('')}${text('reason','Reason for any variance',c.reason??'')}<button>Save observed counts</button></form><div class="actions">${c.lines.every(l=>l.observed!==null)?`<button data-approve="${c.id}">Approve correction</button>`:''}<button class="secondary" data-cancel-count="${c.id}">Cancel count</button></div>`:`<p>${esc(c.reason??'Count cancelled')}</p><p>${c.lines.map(l=>`${esc(name(l.product_id))}: ${l.expected} expected → ${l.observed??'—'} counted`).join('<br>')}</p>`}</section>`).join('')}<details class="panel"><summary>Movement and adjustment history</summary><div class="actions"><button id="load-history">Load next 100 records</button><a href="/api/export?kind=history">Export history CSV (up to 10,000)</a></div><div id="history"></div></details>`}`;}
function truckView(match=()=>true){const heavy=view!=='TRUCK2';const trucks=state.trucks.filter(match);return `${!trucks.length?emptyState('TRUCKS',heavy?'No 12.5 tonne trucks yet.':'No 2 tonne trucks yet.','Add one below or with the +1 button on the Equipment page.'):''}${trucks.map(t=>`<section class="panel" data-drop="${t.id}"><div class="row"><h2>▰ ${esc(t.name)}</h2><span class="badge">${esc(t.status.replaceAll('_',' '))}</span></div>${deckSVG(t,state.containers)}<div class="metrics compact"><div><strong>${kg(t.loadedWeight)}</strong><span>Loaded</span></div><div><strong>${kg(t.reservedWeight)}</strong><span>Reserved</span></div><div><strong>${kg(t.loadedWeight===null||t.reservedWeight===null?null:t.payload-t.loadedWeight-t.reservedWeight)}</strong><span>Remaining / ${kg(t.payload)}</span></div><div><strong>${(100*t.deckArea/(t.length*t.width)).toFixed(1)}%</strong><span>Ground deck occupied</span></div></div><p>At: ${esc(name(t.at))} · Destination: ${t.destination?esc(name(t.destination)):'Not assigned'}</p><div class="actions">${truckRemoveButton(t)}</div>${manifestPanel(state.deliveries.find(d=>d.id===t.delivery),'Delivery docket on board')}${t.status!=='IN_TRANSIT'?`<form data-dispatch="${t.id}">${select('destination','Travel destination',[...state.sites.filter(s=>s.status==='ACTIVE'),...state.yards].filter(s=>s.id!==t.at))}<div class="actions"><button>Dispatch truck</button><button type="button" class="secondary" data-unload="${t.id}">Unload at current location</button></div></form>`:'<p>Truck travelling. Its cargo remains truck stock.</p>'}${containerCards(t.id)}</section>`).join('')}${account.permissions.includes('operations.manage')?form('truck',heavy?'Add a 12.5 tonne truck':'Add a 2 tonne truck',text('name','Truck name',`${heavy?'T':'L'}-${String(trucks.length+1).padStart(2,'0')}`)+select('yard','Home yard',state.yards)+number('length','Deck length (mm)',heavy?6000:4200,1)+number('width','Deck width (mm)',heavy?2100:1900,1)+number('payload','Payload (g)',heavy?12500000:2000000,1),'Add truck'):''}`;}
function siteView(){return `${!state.sites.length?emptyState('SITES','Ready for your next site.','Create a site to track deliveries, returns and stock.'):''}${state.sites.map(s=>`<section class="panel"><div class="row"><h2>⚑ ${esc(s.name)}</h2><span class="badge">${s.status}</span></div><p>${esc(s.address)}${s.client?' · '+esc(s.client):''}${s.email?' · '+esc(s.email):''} · <strong>${dims(s)}</strong> · height ${((s.height??10000)/1000).toFixed(1)} m</p>${yardSVG(s,state.containers,state.tasks,selected,[],state.resources,null,{balances:state.balances,products:state.products,view:{...DEFAULT_VIEW,tilt:planView.tilt}})}${account.permissions.includes('operations.manage')&&s.status==='ACTIVE'&&editingSite?.id!==s.id?`<div class="actions"><button class="secondary" data-edit-site="${s.id}">Edit site boundary</button></div>`:''}${account.permissions.includes('operations.manage')&&s.status==='ACTIVE'?form('site-details-'+s.id,'Edit site details',text('name','Site name',s.name)+text('address','Address / location',s.address)+'<label>Client company<input name="client" maxlength="250" value="'+esc(s.client??'')+'"></label><label>Site contact<input name="contact" maxlength="250" value="'+esc(s.contact??'')+'"></label><label>Contact email<input name="email" type="email" maxlength="254" value="'+esc(s.email??'')+'"></label><label>Contact phone<input name="phone" maxlength="60" value="'+esc(s.phone??'')+'"></label>'+(account.users.length?'<label>Assigned supervisor<select name="supervisor"><option value="">Not assigned</option>'+options(account.users,'name',s.supervisor)+'</select></label>':'<p class="muted">Supervisor: '+esc(s.supervisorName??'Not assigned')+'</p>'),'Save site details'):''}${editingSite?.id===s.id?builder():''}${state.deliveries.filter(d=>d.to===s.id&&d.manifest?.length).slice(-5).reverse().map(d=>manifestPanel(d,'Delivery docket')).join('')}${containerCards(s.id)}<div class="drop-zones">${state.trucks.filter(t=>t.at===s.id&&t.status==='AT_SITE').map(t=>`<div class="drop-zone" data-drop="${t.id}"><strong>▰ ${esc(t.name)}</strong><span>At this site · drop a stillage or cage to load it for return</span>${truckRemoveButton(t)}</div>`).join('')}</div>${account.permissions.includes('operations.manage')&&s.status!=='ARCHIVED'?`<button class="secondary" data-archive="${s.id}">Archive empty site</button>`:''}</section>`).join('')}${account.permissions.includes('operations.manage')?form('site','Create a site',text('name','Site name')+text('address','Address / location')+'<label>Client company (optional)<input name="client" maxlength="250"></label><label>Site contact (optional)<input name="contact" maxlength="250"></label><label>Contact email (optional)<input name="email" type="email" maxlength="254"></label><label>Contact phone (optional)<input name="phone" maxlength="60"></label>'+`<label>Assigned supervisor<select name="supervisor"><option value="">Not assigned</option>${options(account.users)}</select></label>`,'Create site'):''}`;}
function requestView(){return `${!state.requests.length&&!(state.loadLists??[]).length?emptyState('REQUESTS','Every delivery starts with a yard list.','List the materials for a site below; the yard reserves exact packs, loads the truck and the list travels as the delivery docket.'):''}${loadListForm()}${yardListsPanel(l=>!l.cancelled&&l.status!=='DELIVERED',true)}${yardListsPanel(l=>l.cancelled||l.status==='DELIVERED',true)}${form('request','Quick single-line request',select('site','Destination site',state.sites.filter(s=>s.status==='ACTIVE'))+select('product','Exact product variant',enabledProducts())+qty()+text('notes','Delivery notes','Demonstration delivery'),'Send to yard')}${state.requests.filter(r=>!r.loadList).map(r=>`<section class="panel"><div class="row"><h2>${esc(name(r.site))}</h2><span class="badge">${esc(r.status)}</span></div><p><strong>${r.quantity} × ${esc(name(r.product))}</strong></p><p>Allocated: ${r.allocated} · Placed at site: ${r.delivered} · Exact quantity only.</p>${r.status==='REQUESTED'&&account.permissions.includes('operations.manage')?`<form data-allocate="${r.id}">${select('truck','Loading truck',state.trucks.filter(t=>t.status==='AT_YARD'))}<button>Plan packs & load truck</button></form>`:''}${['REQUESTED','ALLOCATED','PARTIALLY ALLOCATED'].includes(r.status)&&account.permissions.includes('requests.create')?`<div class="actions"><button type="button" class="secondary" data-cancel-request="${r.id}">Cancel request</button></div>`:''}</section>`).join('')}`;}
function detail(){const c=state.containers.find(c=>c.id===selected);if(!c)return '';const lines=state.balances.filter(l=>l.container===c.id);const atYardOrSite=state.yards.some(y=>y.id===c.location)||state.sites.some(s=>s.id===c.location);return `<section class="panel selected-detail"><div class="row"><h2>${esc(c.name)} · ${esc(c.type)}</h2>${account.permissions.includes('operations.manage')?`<button class="secondary" data-retire="${c.id}" data-retire-label="${esc(c.name)}" ${lines.length||!atYardOrSite?'disabled':''}>Remove stillage / cage</button>`:''}<button class="secondary" id="close-detail">Close</button></div><p>${esc(name(c.location))} · ${esc(c.condition)} · ${c.envelopeLength} × ${c.envelopeWidth} × ${c.height} mm · tare ${kg(c.tare)}</p><h3>Contents</h3>${lines.length?lines.map(l=>{const available=l.quantity-l.reserved,canRemove=atYardOrSite&&available>0&&account.permissions.includes('stock.adjust');return `<div class="content-line"><p><strong>${l.quantity} × ${esc(name(l.product_id))}</strong> · ${kg(state.products.find(p=>p.id===l.product_id)?.unitWeight)} each${l.reserved?` · ${l.reserved} reserved`:''}${available>0?` · <span class="badge available">${available} available</span>`:''}</p>${canRemove?`<form id="remove-line-${c.id}-${l.product_id}" class="inline-form remove-line" data-focus-scope="remove:${l.product_id}"><label>Remove<input type="number" name="quantity" value="${available}" min="1" max="${available}" step="1" required></label>${text('reason','Reason','Materials list correction')}<button class="secondary">Remove from this stillage</button></form>`:''}</div>`;}).join(''):'<p>Empty stillage / cage</p>'}${lines.length&&atYardOrSite&&account.permissions.includes('operations.manage')&&account.permissions.includes('stock.adjust')?`<details class="scrap-container"><summary>Remove this stillage anyway</summary><p class="muted">This takes the stillage itself off the yard along with everything still on it — ${lines.reduce((s,l)=>s+l.quantity,0)} piece${lines.reduce((s,l)=>s+l.quantity,0)===1?'':'s'} across ${lines.length} product${lines.length===1?'':'s'}. Use this only when the stillage and its load are gone for good — lost, damaged beyond use or otherwise unrecoverable — not for a quantity mistake (use Remove on the line above instead).</p><form id="scrap-container">${text('reason','Reason')}<button class="secondary">Remove stillage &amp; write off contents</button></form></details>`:''}<p class="muted">Source yard: ${c.sourceYard?esc(name(c.sourceYard)):'—'} · Last placed: ${esc(c.placedAt??'Not moved yet')}</p><form id="move">${select('destination','Move to',[...state.yards,...state.trucks,...state.sites.filter(s=>s.status==='ACTIVE')])}<details><summary>Exact placement (optional)</summary><div class="form-grid">${number('x','X (mm)',0,-1000000)}${number('y','Y (mm)',0,-1000000)}<label>Rotation<select name="rotation"><option>0</option><option>90</option></select></label><label>Supporting stillage / cage<select name="support"><option value="">Ground level</option>${options(state.containers.filter(o=>o.id!==c.id))}</select></label></div><label class="inline-check"><input name="exact" type="checkbox"> Use these coordinates</label></details><button>Confirm move request</button></form>${account.permissions.includes('operations.manage')?form('condition','Change condition',select('condition','Condition',['SERVICEABLE','DAMAGED','QUARANTINED'].map(id=>({id,name:id})))+text('reason','Condition reason'),'Record condition')+form('container-settings','Configure stillage / cage weight & loaded envelope',number('tare','Tare (g)',c.tare??'')+number('envelopeLength','Loaded length (mm)',c.envelopeLength,1)+number('envelopeWidth','Loaded width (mm)',c.envelopeWidth,1)+text('reason','Configuration reason','Company configured'),'Save frame settings'):''}</section>`;}
function bindScrapContainer(){document.querySelector('#scrap-container')?.addEventListener('submit',async event=>{event.preventDefault();const node=event.target,data=Object.fromEntries(new FormData(node));if(!confirm('Remove this stillage and write off everything still on it? This cannot be undone.'))return;const button=node.querySelector('button');button.disabled=true;try{const result=await command('scrapContainer',{id:selected,reason:data.reason});notify(result.message);selected=null;await refresh(true);}catch(e){notify(e.message);button.disabled=false;}});}
function bindViews(){
  bind('parking','parking',d=>({id:state.yards[0].id,side:d.side,vehicleLength:Math.round(d.vehicleLength*1000),vehicleWidth:Math.round(d.vehicleWidth*1000),clearance:Math.round(d.clearance*1000)}));
  document.querySelector('#container [name=type]')?.addEventListener('change',e=>{const f=e.target.form,cage=e.target.value==='CAGE';for(const key of ['length','envelopeLength'])f.elements.namedItem(key).value=cage?1200:2000;for(const key of ['width','envelopeWidth'])f.elements.namedItem(key).value=1000;f.elements.namedItem('name').value=(cage?'C-':'S-')+String(state.containers.length+1).padStart(3,'0');});
  bind('condition','condition',d=>({...d,id:selected}));bind('container-settings','containerSettings',d=>({...d,id:selected}));bind('resources','resources');bind('container','container');bind('opening','opening');bind('truck','truck');bind('site','site');for(const s of state.sites)bind('site-details-'+s.id,'siteDetails',d=>({...d,id:s.id}));if(selected)for(const l of state.balances.filter(l=>l.container===selected))bind('remove-line-'+selected+'-'+l.product_id,'removeStock',d=>({container:selected,product:l.product_id,quantity:d.quantity,reason:d.reason}));bind('request','request');bind('count','count');bind('move','queue',d=>({container:selected,destination:d.destination,...(d.exact?{position:{x:d.x,y:d.y,rotation:Number(d.rotation),support:d.support||null}}:{})}));
  document.querySelector('#close-detail')?.addEventListener('click',()=>{selected=null;render();});
  bindScrapContainer();
  document.querySelector('#edit-yard')?.addEventListener('click',()=>{editingSite=null;editingYard=state.yards[0];segments=structuredClone(editingYard.segments);closed=true;fixtureRows=structuredClone(editingYard.fixtures??[]);placingFixture=null;layoutDraft=null;layoutCheck=null;render();});
  document.querySelectorAll('[data-edit-site]').forEach(b=>b.onclick=()=>{editingYard=null;editingSite=state.sites.find(s=>s.id===b.dataset.editSite);segments=structuredClone(editingSite.segments??rectSegments(editingSite));closed=true;render();});
  document.querySelector('#cancel-builder')?.addEventListener('click',()=>{editingSite=null;editingYard=null;segments=[];closed=false;fixtureRows=null;placingFixture=null;render();});
  document.querySelectorAll('[data-fixture-add]').forEach(b=>b.onclick=()=>{const [kind,label,w,h]=FIXTURE_TYPES.find(t=>t[0]===b.dataset.fixtureAdd);fixtureRows??=[];fixtureRows.push({kind,name:label,w,h,...freeSpotFor(w,h)});placingFixture=null;render();});
  document.querySelectorAll('[data-fixture-remove]').forEach(b=>b.onclick=()=>{fixtureRows.splice(Number(b.dataset.fixtureRemove),1);placingFixture=null;render();});
  document.querySelectorAll('[data-fixture-kind]').forEach(s=>s.onchange=()=>{const f=fixtureRows[Number(s.dataset.fixtureKind)],t=FIXTURE_TYPES.find(t=>t[0]===s.value);const wasDefault=FIXTURE_TYPES.some(x=>x[1]===f.name);f.kind=t[0];if(wasDefault)f.name=t[1];f.w=t[2];f.h=t[3];render();});
  document.querySelectorAll('[data-fixture-name]').forEach(i=>i.onchange=()=>{fixtureRows[Number(i.dataset.fixtureName)].name=i.value;});
  document.querySelectorAll('[data-fixture]').forEach(i=>i.onchange=()=>{const [idx,key]=i.dataset.fixture.split(':');fixtureRows[Number(idx)][key]=Math.round(Number(i.value)*1000);render();});
  document.querySelectorAll('[data-fixture-place]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.fixturePlace);placingFixture=placingFixture===i?null:i;render();});
  const fixturePreview=document.querySelector('#builder .yard-svg');if(fixturePreview&&placingFixture!==null){fixturePreview.style.cursor='crosshair';fixturePreview.addEventListener('click',e=>{const f=fixtureRows?.[placingFixture];if(!f)return;const at=planPoint(fixturePreview,e);f.x=Math.round((at.x-f.w/2)/500)*500;f.y=Math.round((at.y-f.h/2)/500)*500;placingFixture=null;render();});}
  bind('save-site','siteBoundary',({loadingX,loadingY,gateX,gateY,...d})=>({...d,id:editingSite.id,segments,closed,loading:{x:Math.round(loadingX*1000),y:Math.round(loadingY*1000)},gate:{x:Math.round(gateX*1000),y:Math.round(gateY*1000)}}),()=>{editingSite=null;segments=[];closed=false;});
  const segment=document.querySelector('#segment');if(segment)segment.onsubmit=e=>{e.preventDefault();const data=new FormData(segment);segments.push({direction:data.get('direction'),length:Math.round(Number(data.get('metres'))*1000)});closed=false;render();};
  document.querySelectorAll('[data-segment-dir]').forEach(el=>el.onchange=()=>{segments[Number(el.dataset.segmentDir)].direction=el.value;closed=false;render();});document.querySelectorAll('[data-segment-length]').forEach(el=>el.onchange=()=>{segments[Number(el.dataset.segmentLength)].length=Math.round(Number(el.value)*1000);closed=false;render();});document.querySelectorAll('[data-segment-remove]').forEach(el=>el.onclick=()=>{segments.splice(Number(el.dataset.segmentRemove),1);closed=false;render();});
  document.querySelector('#undo-segment')?.addEventListener('click',()=>{segments.pop();closed=false;render();});document.querySelector('#reset-segments')?.addEventListener('click',()=>{if(confirm('Clear all unsaved yard segments?')){segments=[];closed=false;render();}});document.querySelector('#close-yard')?.addEventListener('click',()=>{closed=true;render();});
  bind('save-yard','yard',({loadingX,loadingY,gateX,gateY,...d})=>({...d,segments,closed,loading:{x:Math.round(loadingX*1000),y:Math.round(loadingY*1000)},gate:{x:Math.round(gateX*1000),y:Math.round(gateY*1000)},fixtures:(fixtureRows??[]).map(f=>({kind:f.kind,name:f.name,x:Math.round(f.x),y:Math.round(f.y),w:Math.round(f.w),h:Math.round(f.h)})),...(editingYard?{id:editingYard.id}: {})}),()=>{editingYard=null;segments=[];closed=false;fixtureRows=null;placingFixture=null;});
  document.querySelector('#stock-search')?.addEventListener('input',e=>{document.querySelectorAll('[data-stock-row]').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(e.target.value.toLowerCase()));});
  document.querySelectorAll('[data-component-tab]').forEach(b=>b.onclick=()=>{componentTab=b.dataset.componentTab;render();});
  document.querySelectorAll('[data-stock-tab]').forEach(b=>b.onclick=()=>{stockTab=b.dataset.stockTab;render();});bindPurge();bind('purchase','purchase');bind('remove-stock','removeStock');
  document.querySelector('#add-load-line')?.addEventListener('click',()=>{const box=document.querySelector('#load-lines'),i=box.children.length;box.insertAdjacentHTML('beforeend','<div class="load-line"><label>Product<select name="product'+i+'"><option value="">— none —</option>'+options(enabledProducts())+'</select></label><label>Quantity<input type="number" name="quantity'+i+'" min="0" step="1" value="0"></label></div>');});
  const loadForm=document.querySelector('#load-list');if(loadForm)loadForm.onsubmit=async e=>{e.preventDefault();const fd=new FormData(loadForm),lines=[];for(let i=0;fd.has('product'+i);i++){const product=fd.get('product'+i),quantity=Number(fd.get('quantity'+i));if(product&&quantity>0)lines.push({product,quantity});}if(!lines.length){notify('Add at least one product line with a quantity.');return;}try{await command('createLoadList',{name:fd.get('name'),site:fd.get('site'),notes:fd.get('notes'),lines});notify('Yard list created. Reserve packs to start loading.');await refresh(true);}catch(error){notify(error.message);}};
  document.querySelectorAll('[data-allocate-list]').forEach(form=>form.onsubmit=async e=>{e.preventDefault();try{const result=await command('allocateLoadList',{id:form.dataset.allocateList,truck:new FormData(form).get('truck')});const short=result.outcome.filter(o=>o.status==='SHORT');notify(short.length?`${result.outcome.length-short.length} line(s) reserved; ${short.length} short: ${short.map(o=>o.reason).join(' ')}`:'Every line reserved. Loading tasks queued.');await refresh(true);}catch(error){notify(error.message);}});
  action('[data-cancel-list]',e=>command('cancelLoadList',{id:e.dataset.cancelList,reason:'Remaining lines cancelled by user'}));
  document.querySelectorAll('[data-allocate]').forEach(form=>form.onsubmit=async e=>{e.preventDefault();try{await command('allocate',{id:form.dataset.allocate,truck:new FormData(form).get('truck')});await refresh(true);notify('Exact pack plan reserved. Loading tasks queued.');}catch(error){notify(error.message);}});
  document.querySelectorAll('[data-dispatch]').forEach(form=>form.onsubmit=async e=>{e.preventDefault();try{await command('dispatch',{id:form.dataset.dispatch,destination:new FormData(form).get('destination')});await refresh(true);}catch(error){notify(error.message);}});
  document.querySelectorAll('[data-count]').forEach(form=>form.onsubmit=async e=>{e.preventDefault();const fd=new FormData(form),count=state.counts.find(c=>c.id===form.dataset.count);try{await command('observe',{id:count.id,observed:count.lines.map((l,i)=>Number(fd.get(`line${i}`))),reason:fd.get('reason')});await refresh(true);}catch(error){notify(error.message);}});
  action('[data-cancel-request]',e=>command('cancelRequest',{id:e.dataset.cancelRequest,reason:'User cancelled unstarted remainder'}));
  action('[data-approve]',e=>command('approveCount',{id:e.dataset.approve}));action('[data-cancel-count]',e=>command('cancelCount',{id:e.dataset.cancelCount}));action('[data-unload]',e=>command('unload',{id:e.dataset.unload}));action('[data-archive]',e=>command('archive',{id:e.dataset.archive}));
  document.querySelector('#load-history')?.addEventListener('click',async()=>{try{const rows=await api(`history?after=${historyCursor}&limit=100`);historyCursor=rows.at(-1)?.sequence??historyCursor;document.querySelector('#history').innerHTML=rows.map(l=>`<p>#${l.sequence} ${esc(l.event)} · ${l.quantity} · ${esc(l.reason)}<br><time>${esc(l.created_at)}</time></p>`).join('')||'<p>No more records.</p>';}catch(e){notify(e.message);}});
  bindOverview();
}

export function catalogueSettings(){return `<section class="panel"><h2>Catalogue & provenance</h2><p>All suggested demo data is synthetic. No manufacturer documents were imported.</p><button id="seed-demo" ${state?.products.length?'disabled':''}>Add synthetic demo catalogue</button></section>${state?purgeButton():''}${account?.permissions.includes('operations.manage')?`<details class="panel"><summary>Import reviewed catalogue batches</summary><p>Choose one or more reviewed JSON batch files (for example the supplier batches in <code>catalogues/verified/</code>). Each file imports atomically: a duplicate or invalid row rejects that whole file. Imports add products only — no stock is created.</p><label>Batch files<input type="file" id="import-batches" accept=".json,application/json" multiple></label><div class="actions"><button type="button" id="import-run">Import selected files</button></div><div id="import-log" class="muted"></div></details>`:''}${state?form('override-product','Configure a product’s operational values',select('product','Product',state.products.filter(p=>!p.retired))+number('unitWeight','Unit weight (g)',5000)+number('packQuantity','Operating full-pack quantity',100,1)+text('reason','Reason','Company-configured DEMO values'),'Save company override'):''}`;}
function bindPurge(){document.querySelector('#purge-demo')?.addEventListener('click',async()=>{if(!confirm('Remove every demonstration product and all of its stock from this company? Real products and stock are not affected.'))return;try{const r=await command('purgeDemo',{});notify(`Removed ${r.products} demonstration product(s) and ${r.pieces} piece(s).`);if(view==='HOME'||document.querySelector('#seed-demo')){state=await api('state');settings();}else await refresh(true);}catch(e){notify(e.message);}});}
export function bindCatalogue(){bindPurge();document.querySelector('#import-run')?.addEventListener('click',async()=>{const input=document.querySelector('#import-batches'),log=document.querySelector('#import-log'),files=[...(input?.files??[])].sort((a,b)=>a.name.localeCompare(b.name));if(!files.length){notify('Choose at least one batch file first.');return;}const button=document.querySelector('#import-run');button.disabled=true;let imported=0;log.innerHTML='';for(const file of files){try{const batch=JSON.parse(await file.text());if(!Array.isArray(batch.products))throw new Error('Not a batch file: expected {name, products:[...]}');const result=await command('importCatalogue',{name:batch.name??file.name,products:batch.products});imported+=result.products.length;log.insertAdjacentHTML('beforeend',`<p>✔ ${esc(file.name)} — ${result.products.length} product(s)</p>`);}catch(e){log.insertAdjacentHTML('beforeend',`<p class="error-text">✖ ${esc(file.name)} — ${esc(e.message)}</p>`);}}button.disabled=false;notify(`Imported ${imported} product(s).`);state=await api('state');});document.querySelector('#seed-demo')?.addEventListener('click',async()=>{try{await command('seed',{});state=await api('state');notify('Synthetic catalogue added. Return to the yard to add stillages, cages and stock.');settings();}catch(e){notify(e.message);}});bind('override-product','override');}

function workerPanel(yard){const workers=state.resources.filter(r=>r.type==='WORKER'&&r.location===yard.id),w=workers.find(r=>r.id===selectedWorker);return '<section class="worker-command-panel"><div class="worker-roster">'+workers.map(r=>'<button class="secondary '+(r.id===selectedWorker?'worker-active':'')+'" data-worker-pick="'+esc(r.id)+'">'+esc(r.name)+'</button>').join('')+'</div>'+forkliftRoster(yard)+(w?'<button class="worker-close secondary" data-worker-clear aria-label="Deselect worker">&times;</button><div class="worker-orders"><div class="worker-portrait" aria-hidden="true">'+'<svg viewBox="0 0 64 72" aria-hidden="true"><path d="M10 68v-18q22-15 44 0v18" fill="#e8dc55"/><circle cx="32" cy="30" r="15" fill="#dfaf80"/><path d="M14 26q0-23 18-23t18 23z" fill="#f1cd48"/><path d="M10 27h44M23 47v21M42 47v21" stroke="#fff0b9" stroke-width="5"/></svg></div><div><div class="eyebrow">SELECTED WORKER</div><h2>'+esc(w.name)+'</h2><p>'+(w.task?'Assigned to material handling':w.mountedOn?forkliftStatus(w):w.mountTarget?'Walking to '+esc(name(w.mountTarget)):w.walk?(w.walk.job?'Walking to a yard job':'Walking to destination'):w.job?'On a yard job':w.workerMode==='HOLD'?'Holding position':'Ready for automatic work')+'</p>'+(w.board?'<div class="board-line now"><b>NOW</b><span class="text">'+esc(w.board.now.title)+'</span>'+(w.board.now.progress!=null?'<i class="bar" data-progress="'+w.id+'"><span style="width:'+w.board.now.progress+'%"></span></i>':'')+'</div>'+(w.board.next?'<div class="board-line"><b>NEXT</b><span class="text">'+esc(w.board.next.title)+'</span></div>':''):'')+(w.workerReason?'<p class="error-text">'+esc(w.workerReason)+'</p>':'')+'</div></div>'+(account.permissions.includes('operations.manage')?'<div class="worker-buttons"><button data-worker-order="MOVE" '+(w.task?'disabled':'')+'>'+(w.mountedOn?'Drive':'Move')+'</button><button class="secondary" data-worker-order="STOP" '+(w.task?'disabled':'')+'>Stop</button><button class="secondary" data-worker-order="HOLD" '+(w.task?'disabled':'')+'>Hold position</button><button class="secondary" data-worker-order="AUTO" '+(w.task||w.mountedOn?'disabled':'')+'>Return to work</button>'+mountControls(w,yard)+'<button class="secondary" data-retire="'+esc(w.id)+'" data-retire-label="worker '+esc(w.name)+'" '+(w.task||w.walk||w.mountedOn||w.mountTarget?'disabled':'')+'>Remove worker</button></div>':'')+(workerMoveMode==='PLACE'?placementPanel():'')+'<p class="worker-help">'+(workerMoveMode==='PLACE'?'Move the pointer to preview. Click to pin, adjust or rotate, then Confirm placement. R rotates; arrow keys nudge.':workerMoveMode?'Click open ground to set the destination.':w.mountedOn?'Right-click ground to drive. Select a stillage, then Pick up. Place load lets you choose its new position.':'Left-click selects. Right-click open ground moves. Hold keeps the worker out of automatic jobs; Return to work makes them available again.')+'</p>':'<h2>Your yard crew</h2><p>'+(workers.length?'Select a worker on the plan or above to give orders.':'Configure workers below to add your crew to the yard.')+'</p>')+'</section>';}
function forkliftRoster(yard){if(!account.permissions.includes('operations.manage'))return '';const machines=state.resources.filter(r=>r.type==='FORKLIFT'&&r.location===yard.id);if(!machines.length)return '';return '<div class="forklift-roster">'+machines.map(m=>{const busy=m.task||m.driver||m.claimedBy||m.cargo||m.drive;return '<span><strong>'+esc(m.name)+'</strong> · '+(m.driver?'Driver: '+esc(name(m.driver)):m.task?'On a task':m.claimedBy?'Worker approaching':'Available')+'</span><button type="button" class="secondary" data-retire="'+esc(m.id)+'" data-retire-label="'+esc(m.name)+'" '+(busy?'disabled':'')+'>Remove forklift</button>';}).join('')+'</div>';}
function bindWorkers(){
 document.querySelector('[data-worker-clear]')?.addEventListener('click',()=>{selectedWorker=null;workerMoveMode=false;returnView=null;render();});
 const pick=id=>{if(id!==selectedWorker){workerMoveMode=false;returnView=null;}selectedWorker=id;render();};
 document.querySelectorAll('[data-worker]').forEach(el=>{el.onclick=e=>{e.stopPropagation();pick(el.dataset.worker);};el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();pick(el.dataset.worker);}};});
 document.querySelectorAll('[data-worker-pick]').forEach(el=>el.onclick=()=>pick(el.dataset.workerPick));
 document.querySelectorAll('[data-worker-order]').forEach(el=>el.onclick=async()=>{const order=el.dataset.workerOrder,fromRow=!!el.dataset.workerId,id=el.dataset.workerId??selectedWorker;if(order==='MOUNT'){try{const forklift=fromRow?(document.querySelector('[data-mount-select="'+id+'"]')?.value??mountChoice.get(id)):document.querySelector('#mount-forklift').value;await command('workerCommand',{id,order,forklift});await refresh(true);}catch(e){notify(e.message);}return;}if(order==='PICKUP'){try{await command('workerCommand',{id,order,container:selected});await refresh(true);}catch(e){notify(e.message);}return;}if(order==='PLACE'){beginPlacement();return;}if(order==='MOVE'){const target=fromRow?(document.querySelector('[data-move-target="'+id+'"]')?.value??moveTarget.get(id)??'plan'):'plan';if(target==='plan'){selectedWorker=id;workerMoveMode='MOVE';if(fromRow){returnView='WORKERS';view='HOME';}render();notify('Click open ground to move, or right-click a destination. Esc cancels.');if(fromRow)document.querySelector('.scene')?.scrollIntoView({block:'start'});return;}try{const w=state.resources.find(r=>r.id===id);await command('workerCommand',{id,order,target,...(w?.mountedOn?{}:{resume:true})});await refresh(true);}catch(e){notify(e.message);}return;}try{await command('workerCommand',{id,order,...(order==='DISMOUNT'&&fromRow?{resume:true}:{})});workerMoveMode=false;await refresh(true);}catch(e){notify(e.message);}});
 document.querySelectorAll('[data-forklift]').forEach(el=>{const choose=()=>{const m=state.resources.find(r=>r.id===el.dataset.forklift);if(m.driver){pick(m.driver);}else{notify(m.claimedBy?'A worker is walking to this forklift.':'Select a worker, then use Mount Forklift.');}};el.onclick=e=>{e.stopPropagation();choose();};el.onkeydown=e=>{if(e.key==='Enter'){choose();}};});
 document.querySelectorAll('[data-plan]').forEach(b=>b.onclick=()=>{const [kind,val]=b.dataset.plan.split(':');if(kind==='zoom'){planView.zoom=Math.min(8,Math.max(0.4,planView.zoom*Number(val)));saveView();applyView();return;}if(kind==='rotate'){planView.rotate=((planView.rotate+Number(val))%360+360)%360;}else if(kind==='tilt'){planView.tilt=!planView.tilt;}else if(kind==='reset'){planView={...DEFAULT_VIEW,tilt:planView.tilt};}saveView();render();});
 const svg=document.querySelector('.scene .yard-svg');if(!svg||!['YARD','HOME'].includes(view))return;
 svg.addEventListener('wheel',e=>{e.preventDefault();const factor=e.deltaY<0?1.15:1/1.15,next=Math.min(8,Math.max(0.4,planView.zoom*factor)),k=next/planView.zoom;const pt=svg.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const cursor=pt.matrixTransform(svg.getScreenCTM().inverse()),C=planFrame(state.yards[0],planView).screenCentre;planView.pan={x:cursor.x-C.x-k*(cursor.x-C.x-planView.pan.x),y:cursor.y-C.y-k*(cursor.y-C.y-planView.pan.y)};planView.zoom=next;saveView();applyView();},{passive:false});
 let drag=null;svg.addEventListener('pointerdown',e=>{if(e.button!==0||e.target.closest('[data-select],[data-worker],[data-forklift]'))return;const pt=svg.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const at=pt.matrixTransform(svg.getScreenCTM().inverse());drag={x:at.x,y:at.y,pan:{...planView.pan},moved:false,client:{x:e.clientX,y:e.clientY}};});
 svg.addEventListener('pointermove',e=>{if(!drag||!(e.buttons&1))return;if(!drag.moved&&Math.hypot(e.clientX-drag.client.x,e.clientY-drag.client.y)<6)return;drag.moved=true;svg.style.cursor='grabbing';const pt=svg.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const at=pt.matrixTransform(svg.getScreenCTM().inverse());planView.pan={x:drag.pan.x+(at.x-drag.x),y:drag.pan.y+(at.y-drag.y)};applyView();});
 const endDrag=()=>{if(!drag)return;if(drag.moved){suppressPlanClick=true;saveView();setTimeout(()=>{suppressPlanClick=false;},250);}svg.style.cursor='';drag=null;};svg.addEventListener('pointerup',endDrag);svg.addEventListener('pointerleave',endDrag);
 if(layoutDraft&&['YARD','HOME'].includes(view))bindPlanner(svg,state.yards[0]);
 const move=async e=>{if(!account.permissions.includes('operations.manage'))return;if(workerMoveMode==='JOB_TARGET'){e.preventDefault();if(suppressPlanClick){suppressPlanClick=false;return;}const at=planPoint(svg,e);jobDraft.where={kind:'point',x:Math.round(at.x/500)*500,y:Math.round(at.y/500)*500};jobDraft.whereKey='plan';workerMoveMode=false;view=returnView??'WORKERS';returnView=null;render();notify('Job spot set at '+(jobDraft.where.x/1000).toFixed(1)+', '+(jobDraft.where.y/1000).toFixed(1)+' m.');return;}if(!selectedWorker)return;e.preventDefault();if(suppressPlanClick){suppressPlanClick=false;return;}const at=planPoint(svg,e);try{await command('workerCommand',{id:selectedWorker,order:workerMoveMode==='PLACE'?'PLACE':'MOVE',x:Math.round(at.x-(workerMoveMode==='PLACE'?0:state.resources.find(r=>r.id===selectedWorker)?.mountedOn?1100:250)),y:Math.round(at.y-(workerMoveMode==='PLACE'?0:state.resources.find(r=>r.id===selectedWorker)?.mountedOn?600:250)),...(returnView&&!state.resources.find(r=>r.id===selectedWorker)?.mountedOn?{resume:true}:{})});workerMoveMode=false;if(returnView){view=returnView;returnView=null;}await refresh(true);}catch(error){notify(error.message);}};
 if(workerMoveMode==='PLACE'){bindPlacement(svg);return;}
 svg.oncontextmenu=move;svg.onclick=e=>{if(suppressPlanClick)return;if(workerMoveMode&&!e.target.closest('[data-worker],[data-select]'))move(e);};
 if(workerMoveMode==='MOVE'||workerMoveMode==='JOB_TARGET'){document.onkeydown=e=>{if(e.key!=='Escape'||e.target.matches?.('input,select,textarea'))return;workerMoveMode=false;if(returnView){view=returnView;returnView=null;}render();};}
}

function mountControls(w,yard){if(w.mountedOn){const m=state.resources.find(r=>r.id===w.mountedOn),c=state.containers.find(r=>r.id===selected);return '<button data-worker-order="PICKUP" '+(m?.cargo||m?.drive||!c||c.location!==yard.id?'disabled':'')+'>Pick up'+(c?' '+esc(c.name):' selected stillage')+'</button><button data-worker-order="PLACE" '+(!m?.cargo||m?.drive?'disabled':'')+'>Place load</button><button class="secondary" data-worker-order="DISMOUNT" '+(w.task||m?.cargo||m?.drive?'disabled':'')+'>Unmount forklift</button>';}const machines=state.resources.filter(r=>r.type==='FORKLIFT'&&r.location===yard.id&&!r.task&&!r.driver&&!r.claimedBy&&Number.isFinite(r.x));return '<label class="mount-choice">Forklift<select id="mount-forklift" '+(!machines.length?'disabled':'')+'>'+ (machines.length?options(machines):'<option>No free forklift</option>')+'</select></label><button data-worker-order="MOUNT" '+(w.task||w.mountTarget||!machines.length?'disabled':'')+'>Mount forklift</button>';}

function forkliftStatus(w){const m=state.resources.find(r=>r.id===w.mountedOn);return esc(name(w.mountedOn))+' - '+(m?.drive?(m.drive.order==='PICKUP'?'Approaching stillage':m.drive.order==='PLACE'?'Moving to placement':'Driving'):m?.cargo?'Carrying '+esc(m.cargoPreview?.name??name(m.cargo)):'Ready to drive')+(m?.manualReason?'<br><span class="error-text">'+esc(m.manualReason)+'</span>':'');}

function beginPlacement(){const w=state.resources.find(r=>r.id===selectedWorker),m=state.resources.find(r=>r.id===w?.mountedOn);if(!m?.cargoPreview)return;workerMoveMode='PLACE';placementDraft={worker:selectedWorker,cargo:m.cargo,x:Math.round(m.x+2200),y:Math.round(m.y),rotation:m.cargoPreview.rotation??0,snap:100,pinned:false,valid:false,message:'Choose a position on the yard plan.'};render();checkPlacement();}
function placementPanel(){if(!placementDraft)return '';const d=placementDraft;return '<form id="placement-form"><div class="row"><h3>Precise placement</h3><span id="placement-size"></span></div><div class="placement-fields"><label>X (mm)<input name="px" type="number" step="1" min="-1000000" max="1000000" value="'+d.x+'" required></label><label>Y (mm)<input name="py" type="number" step="1" min="-1000000" max="1000000" value="'+d.y+'" required></label><label>Grid snap<select name="snap">'+[1,10,50,100,500,1000].map(n=>'<option value="'+n+'" '+(d.snap===n?'selected':'')+'>'+n+' mm</option>').join('')+'</select></label></div><div class="placement-tools"><button type="button" class="secondary" id="placement-rotate">Rotate 90 deg</button><strong id="placement-angle">'+d.rotation+' deg</strong><button type="button" class="secondary" data-nudge="-1,0" aria-label="Nudge left">Left</button><button type="button" class="secondary" data-nudge="1,0" aria-label="Nudge right">Right</button><button type="button" class="secondary" data-nudge="0,-1" aria-label="Nudge up">Up</button><button type="button" class="secondary" data-nudge="0,1" aria-label="Nudge down">Down</button></div><p id="placement-validation" role="status">'+esc(d.message)+'</p><div class="placement-tools"><button id="placement-confirm" disabled>Confirm placement</button><button type="button" class="secondary" id="placement-reposition">Choose another spot</button><button type="button" class="secondary" id="placement-cancel">Cancel</button></div><p class="muted">X/Y locate the top-left corner of the loaded footprint. Typed coordinates are exact; snapping applies to map clicks. Dashed outline shows forklift access.</p></form>';}
function placementLoad(){const w=state.resources.find(r=>r.id===placementDraft?.worker),m=state.resources.find(r=>r.id===w?.mountedOn);return m?.cargo===placementDraft?.cargo?m.cargoPreview:null;}
function paintPlacement(){const d=placementDraft,svg=document.querySelector('.scene .yard-svg'),c=placementLoad();if(!d||workerMoveMode!=='PLACE'||!svg||!c)return;const width=d.rotation===90?c.envelopeWidth:c.envelopeLength,height=d.rotation===90?c.envelopeLength:c.envelopeWidth,color=d.valid?'#36852e':d.pending?'#ba8730':'#bd4636';svg.querySelector('#placement-ghost')?.remove();const g=document.createElementNS('http://www.w3.org/2000/svg','g');g.id='placement-ghost';g.setAttribute('pointer-events','none');if(Number.isFinite(d.x)&&Number.isFinite(d.y))g.innerHTML='<rect x="'+(d.x-2200)+'" y="'+d.y+'" width="2200" height="1200" fill="none" stroke="'+color+'" stroke-width="45" stroke-dasharray="110 70"/>'+(d.plan?.rotationClearance?'<rect x="'+d.plan.rotationClearance.x+'" y="'+d.plan.rotationClearance.y+'" width="'+d.plan.rotationClearance.w+'" height="'+d.plan.rotationClearance.h+'" fill="none" stroke="#bb872e" stroke-width="30" stroke-dasharray="70 90"/>':'')+'<rect x="'+d.x+'" y="'+d.y+'" width="'+width+'" height="'+height+'" fill="'+color+'" fill-opacity=".3" stroke="'+color+'" stroke-width="60"/><path d="M '+(d.x-170)+' '+d.y+' H '+(d.x+170)+' M '+d.x+' '+(d.y-170)+' V '+(d.y+170)+'" stroke="'+color+'" stroke-width="35"/><text x="'+d.x+'" y="'+(d.y-260)+'" font-size="230" fill="'+color+'" stroke="#f8ffeb" stroke-width="12" paint-order="stroke">'+width+' x '+height+' mm / '+d.rotation+' deg</text>';(svg.querySelector('#plan')??svg).append(g);const status=document.querySelector('#placement-validation');if(status){status.textContent=d.message;status.className=d.valid?'placement-valid':d.pending?'':'error-text';}const confirm=document.querySelector('#placement-confirm');if(confirm)confirm.disabled=!d.valid||d.pending;document.querySelector('#placement-angle')?.replaceChildren(document.createTextNode(d.rotation+' deg'));document.querySelector('#placement-size')?.replaceChildren(document.createTextNode(width+' x '+height+' mm'));}
async function checkPlacement(){clearTimeout(placementTimer);const d=placementDraft,seq=++placementSequence;if(!d||workerMoveMode!=='PLACE')return;d.valid=false;d.pending=true;d.plan=null;d.message='Checking footprint, access and rotation clearance...';paintPlacement();try{const plan=await api('placement-preview',{id:d.worker,container:d.cargo,x:d.x,y:d.y,rotation:d.rotation});if(seq!==placementSequence||d!==placementDraft||workerMoveMode!=='PLACE')return;d.plan=plan;d.valid=true;d.message='Position and route clear. Confirm to place.';}catch(e){if(seq!==placementSequence||d!==placementDraft)return;d.message=e.message;}d.pending=false;paintPlacement();}
function editPlacement(x,y){const d=placementDraft;if(!d)return;placementSequence++;d.x=x;d.y=y;d.valid=false;d.pending=true;d.plan=null;d.message='Checking position...';const f=document.querySelector('#placement-form');if(f){f.elements.namedItem('px').value=Number.isFinite(x)?x:'';f.elements.namedItem('py').value=Number.isFinite(y)?y:'';}paintPlacement();clearTimeout(placementTimer);placementTimer=setTimeout(checkPlacement,180);}
function bindPlacement(svg){const d=placementDraft,f=document.querySelector('#placement-form');if(!d||!f)return;paintPlacement();const rotate=()=>{d.rotation=d.rotation===0?90:0;editPlacement(d.x,d.y);};const nudge=(x,y)=>{d.pinned=true;editPlacement(d.x+x*d.snap,d.y+y*d.snap);};const pick=(e,pin)=>{const at=planPoint(svg,e);if(pin)d.pinned=true;editPlacement(Math.round(at.x/d.snap)*d.snap,Math.round(at.y/d.snap)*d.snap);};svg.onpointermove=e=>{if(!d.pinned&&e.pointerType!=='touch')pick(e,false);};svg.addEventListener('click',e=>{e.preventDefault();e.stopImmediatePropagation();pick(e,true);},true);svg.oncontextmenu=e=>{e.preventDefault();pick(e,true);};for(const key of ['px','py'])f.elements.namedItem(key).oninput=()=>{d.pinned=true;editPlacement(f.elements.namedItem('px').valueAsNumber,f.elements.namedItem('py').valueAsNumber);};f.elements.namedItem('snap').onchange=e=>{d.snap=Number(e.target.value);};document.querySelector('#placement-rotate').onclick=rotate;document.querySelectorAll('[data-nudge]').forEach(b=>b.onclick=()=>nudge(...b.dataset.nudge.split(',').map(Number)));document.querySelector('#placement-reposition').onclick=()=>{d.pinned=false;notify('Move over the yard and click to pin a new position.');};const cancel=()=>{placementSequence++;clearTimeout(placementTimer);placementDraft=null;workerMoveMode=false;render();};document.querySelector('#placement-cancel').onclick=cancel;app.onkeydown=e=>{if(workerMoveMode!=='PLACE'||e.target.matches('input,select,textarea'))return;if(e.key.toLowerCase()==='r'){e.preventDefault();rotate();}const keys={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]};if(keys[e.key]){e.preventDefault();nudge(...keys[e.key]);}if(e.key==='Escape')cancel();};f.onsubmit=async e=>{e.preventDefault();if(!d.valid||d.pending)return;document.querySelector('#placement-confirm').disabled=true;try{await command('workerCommand',{id:d.worker,container:d.cargo,order:'PLACE',x:d.x,y:d.y,rotation:d.rotation});placementDraft=null;workerMoveMode=false;placementSequence++;await refresh(true);notify('Exact placement confirmed. Forklift moving.');}catch(error){d.valid=false;d.message=error.message;paintPlacement();}};}

// ----- Stockpile: the HOME icon grids (Stronghold-style). Click adds or takes out the selected step. -----
const GRIDS=[['at-pac','AtPac'],['quickstage','Quickstage'],['tube-clip','Tube & Clip'],['MISC','Miscellaneous']];
const MISC_CATEGORIES=new Set(['Accessories','Tools','Other']);
const gridOf=p=>MISC_CATEGORIES.has(p.category)||!GRIDS.some(([id])=>id===p.system)?'MISC':p.system;
function stockpilePanel(){const yard=state.yards[0];if(!yard||!account.permissions.includes('stock.adjust'))return '';const counts=new Map((state.register??[]).map(r=>[r.product,r.yard]));const products=enabledProducts();const removing=step<0;
 const bar='<section class="panel stockpile-bar"><div class="row"><div><h2>Stockpile</h2><p>Pick how many per click, then click a component. Adding fills the first available stillage and stacks new ones on the shortest pile; taking out comes from the top of the newest pile.</p></div></div><div class="step-row" role="toolbar" aria-label="Amount per click">'+STEPS.map(n=>'<button type="button" class="'+(n===step?'current':'secondary')+(n<0?' minus':'')+'" data-step="'+n+'" aria-pressed="'+(n===step)+'">'+(n>0?'+':'\u2212')+Math.abs(n)+'</button>').join('')+'<span class="step-hint">'+(removing?'Each click takes '+(-step)+' out of the yard':'Each click adds '+step+' to the yard')+'</span>'+(removing?'<label class="step-kind">Reason<select id="stock-reason">'+['Sold to customer','Scrapped / damaged','Hired out (not tracked)','Correction'].map(r=>'<option '+(r===stockReason?'selected':'')+'>'+r+'</option>').join('')+'</select></label>':'<label class="step-kind">Record as<select id="intake-kind"><option value="PURCHASE" '+(intakeKind==='PURCHASE'?'selected':'')+'>Purchase</option><option value="ORIGINAL" '+(intakeKind==='ORIGINAL'?'selected':'')+'>Original stock</option></select></label>')+'</div></section>';
 const grid=([id,title])=>{const list=products.filter(p=>gridOf(p)===id).sort((a,b)=>(a.category??'').localeCompare(b.category??'')||a.name.localeCompare(b.name,undefined,{numeric:true}));let html='',category=null,inYard=0;for(const p of list){const n=counts.get(p.id)??0;inYard+=n;if(p.category!==category){category=p.category;html+='<div class="tile-category">'+esc(category??'Components')+'</div>';}const hay=(p.name+' '+(p.category??'')+' '+(p.reference??'')).toLowerCase();html+='<button type="button" class="tile'+(n?' stocked':'')+'" data-tile="'+p.id+'" data-hay="'+esc(hay)+'" title="'+esc(p.name)+' \u00b7 '+n+' in yard'+(p.unitWeight?' \u00b7 '+kg(p.unitWeight)+' each':'')+'"'+(removing&&!n?' disabled':'')+'>'+componentIcon(p)+'<span class="tile-name">'+esc(p.name)+'</span><b class="tile-count">'+n+'</b></button>';}
  return '<section class="panel stockpile" data-grid="'+id+'"><div class="row"><h2>'+title+'</h2><span class="badge">'+list.length+' items \u00b7 '+inYard.toLocaleString()+' in yard</span></div><input type="search" class="grid-search" data-grid-search="'+id+'" placeholder="Find a component\u2026" value="'+esc(gridSearch[id]??'')+'" aria-label="Search '+title+'"><div class="tile-grid'+(removing?' removing':'')+'">'+(html||'<p class="muted">'+(id==='MISC'?'Accessories, tools and other bits from every system show here once imported.':'Nothing here yet. Import a catalogue batch under Account.')+'</p>')+'</div></section>';};
 return bar+'<div class="stockpile-grids">'+GRIDS.map(grid).join('')+'</div>';}
function applyGridSearch(section){const q=(section.querySelector('.grid-search')?.value??'').trim().toLowerCase();let header=null,visible=0;const finish=()=>{if(header)header.hidden=!visible;};for(const el of section.querySelectorAll('.tile-category,.tile')){if(el.classList.contains('tile-category')){finish();header=el;visible=0;continue;}el.hidden=!!q&&!el.dataset.hay.includes(q);if(!el.hidden)visible++;}finish();}

// ----- Layout planner: drag stillages on the YARD page, then commit the plan as crew instructions. -----
const plannedMoves=()=>Object.entries(layoutDraft?.moves??{}).map(([container,m])=>({container,x:m.x,y:m.y,rotation:m.rotation,support:m.support??null}));
function plannedContainers(){if(!layoutDraft)return state.containers;return state.containers.map(c=>layoutDraft.moves[c.id]?{...c,...layoutDraft.moves[c.id]}:c);}
function pileAbove(id,list){const out=[id];for(let i=0;i<out.length;i++)for(const c of list)if(c.support===out[i]&&!out.includes(c.id))out.push(c.id);return out;}
function unplan(id){if(!layoutDraft)return;for(const cid of pileAbove(id,plannedContainers()))delete layoutDraft.moves[cid];}
const spotText=p=>p.support?'onto '+esc(name(p.support)):(p.x/1000).toFixed(1)+', '+(p.y/1000).toFixed(1)+' m';
function plannerPanel(yard){const moves=Object.entries(layoutDraft.moves),check=layoutCheck;return '<section class="worker-command-panel planner-panel"><div class="row"><div><div class="eyebrow">LAYOUT PLANNER</div><h2>'+moves.length+' move'+(moves.length===1?'':'s')+' planned</h2></div><button type="button" class="secondary" id="planner-exit">Exit planner</button></div><p>Drag a stillage to where it should go. Drop it onto another stillage to stack it there. Whole piles move together. Nothing changes in the yard until you commit the plan; then the crew gets the instructions one by one.</p>'+(moves.length?'<ul class="planner-moves">'+moves.map(([id,m])=>{const c=state.containers.find(c=>c.id===id);return '<li><strong>'+esc(c?.name??id)+'</strong> \u2192 '+spotText(m)+(c&&m.rotation!==c.rotation?' \u00b7 turned':'')+' <button type="button" class="text-button" data-unplan="'+id+'">undo</button></li>';}).join('')+'</ul>':'<p class="muted">No moves yet. Drag a stillage on the plan above.</p>')+(check?'<div class="planner-check '+(check.ok?'ok':'bad')+'">'+(check.ok?'<strong>'+check.steps.length+' instruction'+(check.steps.length===1?'':'s')+' for the crew</strong><ol>'+check.steps.map(s=>'<li>'+esc(s.name)+(s.park?' \u2192 set down for now at ':' \u2192 ')+spotText(s.to)+'</li>').join('')+'</ol>'+(check.warnings?.length?'<p class="error-text">'+check.warnings.map(esc).join(' ')+'</p>':''):'<span class="error-text">'+esc(check.message)+'</span>')+'</div>':'')+'<div class="worker-buttons"><button type="button" class="secondary" id="planner-check" '+(moves.length?'':'disabled')+'>Check plan</button><button type="button" id="planner-commit" '+(moves.length?'':'disabled')+'>Commit this plan</button><button type="button" class="secondary" id="planner-clear" '+(moves.length?'':'disabled')+'>Clear</button></div></section>';}
function layoutsPanel(){const list=(state.layouts??[]).filter(l=>l.status==='ACTIVE');if(!list.length)return '';return list.map(l=>'<section class="panel layout-progress"><div class="row"><h2>'+esc(l.name)+'</h2><span class="badge '+(l.done===l.steps.length?'available':'busy')+'">'+l.done+' of '+l.steps.length+' done</span></div><p>Instructions the crew is working through, in order.</p><ol>'+l.steps.map(s=>'<li class="'+esc(s.state)+'"><strong>'+esc(s.name)+'</strong> '+(s.park?'set down for now at ':'\u2192 ')+spotText(s.to)+' <span class="badge '+(s.state==='COMPLETE'?'available':'')+'">'+esc(s.state.replaceAll('_',' '))+'</span>'+(s.reason?'<br><span class="error-text">'+esc(s.reason)+'</span>':'')+'</li>').join('')+'</ol>'+(account.permissions.includes('operations.manage')?'<div class="actions"><button type="button" class="secondary" data-cancel-layout="'+l.id+'">Cancel remaining steps</button></div>':'')+'</section>').join('');}
function bindPlanner(svg,yard){
 const planned=plannedContainers().filter(c=>c.location===yard.id),byId=new Map(planned.map(c=>[c.id,c]));
 const foot=(c,p)=>({x:p.x,y:p.y,w:p.rotation===90?c.envelopeWidth:c.envelopeLength,h:p.rotation===90?c.envelopeLength:c.envelopeWidth});
 const zones=[{...yard.loading,w:2000,h:1500,name:'loading zone'},...(yard.fixtures??[])];
 const frame=planFrame(yard,planView),k=planView.tilt?0.9:0.22,upUnit={x:-frame.inverse[2],y:-frame.inverse[3]},up=h=>({x:upUnit.x*h*k,y:upUnit.y*h*k});
 const level=id=>{let n=1,cur=byId.get(id),g=0;while(cur?.support&&g++<9){n++;cur=byId.get(cur.support);}return n;};
 const heightBelow=id=>{let h=0,cur=byId.get(id),g=0;while(cur&&g++<9){h+=cur.height;cur=byId.get(cur.support);}return h;};
 let drag=null,last=null;
 const ghost=()=>{svg.querySelector('#layout-ghost')?.remove();if(!drag?.cand)return;const c=byId.get(drag.id),cand=drag.cand,r=foot(c,cand),color=cand.valid?'#36852e':'#bd4636';const g=document.createElementNS('http://www.w3.org/2000/svg','g');g.id='layout-ghost';g.setAttribute('pointer-events','none');g.innerHTML='<rect x="'+r.x+'" y="'+r.y+'" width="'+r.w+'" height="'+r.h+'" fill="'+color+'" fill-opacity=".35" stroke="'+color+'" stroke-width="70" stroke-dasharray="200 120"/><text x="'+(r.x+r.w/2)+'" y="'+(r.y-200)+'" text-anchor="middle" font-size="260" font-weight="700" fill="'+color+'" stroke="#f8ffeb" stroke-width="14" paint-order="stroke">'+esc(c.name)+(drag.pile.length>1?' +'+(drag.pile.length-1):'')+(cand.support?' onto '+esc(byId.get(cand.support).name):'')+(cand.valid?'':' \u2715')+'</text>';(svg.querySelector('#plan')??svg).append(g);};
 const candidate=pt=>{const c=byId.get(drag.id),pile=drag.pile,pileHeight=pile.reduce((s,id)=>s+byId.get(id).height,0);
  const target=planned.filter(t=>!pile.includes(t.id)&&t.type===c.type&&!planned.some(o=>o.support===t.id)).map(t=>{const r=foot(t,t),lift=up(heightBelow(t.id));return {t,r,top:{x:r.x+lift.x,y:r.y+lift.y,w:r.w,h:r.h}};}).filter(({top})=>pt.x>=top.x&&pt.x<=top.x+top.w&&pt.y>=top.y&&pt.y<=top.y+top.h).sort((a,b)=>level(b.t.id)-level(a.t.id))[0];
  if(target){const t=target.t,r=foot(c,{x:t.x,y:t.y,rotation:t.rotation});const tooHigh=level(t.id)+pile.length>7,tooTall=heightBelow(t.id)+pileHeight>(yard.height??10000),ok=!tooHigh&&!tooTall&&containsRect(target.r,r);return {x:t.x,y:t.y,rotation:t.rotation,support:t.id,valid:ok,reason:ok?'':tooHigh?'That pile would be more than 7 high.':tooTall?'That pile would be taller than the yard storage height.':c.name+' does not fit on '+t.name+'.'};}
  const w=drag.rotation===90?c.envelopeWidth:c.envelopeLength,h=drag.rotation===90?c.envelopeLength:c.envelopeWidth,x=Math.round((pt.x-w/2)/500)*500,y=Math.round((pt.y-h/2)/500)*500,r={x,y,w,h};
  const inside=fitsPolygon(r,yard.points),zone=zones.find(z=>overlap(r,z)),hit=planned.find(o=>!pile.includes(o.id)&&!o.support&&overlap(r,foot(o,o)));
  return {x,y,rotation:drag.rotation,support:null,valid:inside&&!zone&&!hit,reason:!inside?'Keep the stillage inside the yard boundary.':zone?'Keep the '+zone.name.toLowerCase()+' clear.':hit?'That spot overlaps '+hit.name+'. Drop onto it to stack instead.':''};};
 svg.addEventListener('pointerdown',e=>{const el=e.target.closest('[data-select]');if(e.button!==0||!el||!byId.has(el.dataset.select))return;const c=byId.get(el.dataset.select);last=planPoint(svg,e);drag={id:c.id,pile:pileAbove(c.id,planned),rotation:c.rotation,start:last,moved:false,cand:null};planDragging=true;try{svg.setPointerCapture(e.pointerId);}catch{}},true);
 svg.addEventListener('pointermove',e=>{if(!drag)return;last=planPoint(svg,e);if(!drag.moved&&Math.hypot(last.x-drag.start.x,last.y-drag.start.y)<250)return;drag.moved=true;svg.style.cursor='grabbing';drag.cand=candidate(last);ghost();});
 const finish=()=>{if(!drag)return;const d=drag;drag=null;planDragging=false;svg.style.cursor='';svg.querySelector('#layout-ghost')?.remove();if(!d.moved)return;suppressPlanClick=true;setTimeout(()=>{suppressPlanClick=false;},300);if(!d.cand?.valid){notify(d.cand?.reason||'That spot is not clear. Choose open ground inside the yard.');return;}for(const id of d.pile){const c=byId.get(id),orig=state.containers.find(o=>o.id===id),m={x:d.cand.x,y:d.cand.y,rotation:d.cand.rotation,support:id===d.id?d.cand.support:c.support};if(m.x===orig.x&&m.y===orig.y&&m.rotation===orig.rotation&&(m.support??null)===(orig.support??null))delete layoutDraft.moves[id];else layoutDraft.moves[id]=m;}layoutCheck=null;setTimeout(render,0);};
 svg.addEventListener('pointerup',finish);svg.addEventListener('pointercancel',finish);
 app.onkeydown=e=>{if(!drag||e.target.matches('input,select,textarea'))return;if(e.key.toLowerCase()==='r'){e.preventDefault();drag.rotation=drag.rotation===0?90:0;if(drag.moved&&last){drag.cand=candidate(last);ghost();}}if(e.key==='Escape'){drag=null;planDragging=false;svg.style.cursor='';svg.querySelector('#layout-ghost')?.remove();}};
}

// ----- Yard fixtures editor (inside the yard boundary editor) -----
const FIXTURE_TYPES=[['ENTRY','Truck entry',4000,3000],['EXIT','Truck exit',4000,3000],['TOILET','Toilet',1500,1500],['OFFICE','Yard office',6000,3000],['CUSTOM','Custom fixture',2000,2000]];
function fixtureEditor(){fixtureRows??=[];const m=v=>String(Math.round(v)/1000);return '<fieldset><legend>Yard fixtures</legend><p class="muted">Truck entry and exit lanes are kept clear of stock. The toilet, yard office and custom fixtures are solid: stock is kept off them and workers and forklifts route around them. Positions are top-left corners in metres from the yard origin. Use Place on plan and click the preview, or type the numbers.</p>'+(fixtureRows.length?'<div class="fixture-head"><span>Type</span><span>Name</span><span>X m</span><span>Y m</span><span>Width m</span><span>Depth m</span><span></span><span></span></div>'+fixtureRows.map((f,i)=>'<div class="fixture-row"><select data-fixture-kind="'+i+'" aria-label="Fixture type">'+FIXTURE_TYPES.map(([k,l])=>'<option value="'+k+'" '+(f.kind===k?'selected':'')+'>'+l+'</option>').join('')+'</select><input data-fixture-name="'+i+'" value="'+esc(f.name)+'" maxlength="60" aria-label="Fixture name">'+['x','y','w','h'].map(k=>'<input type="number" step="0.1" data-fixture="'+i+':'+k+'" value="'+m(f[k])+'" aria-label="'+k+' in metres">').join('')+'<button type="button" class="secondary '+(placingFixture===i?'current':'')+'" data-fixture-place="'+i+'">'+(placingFixture===i?'Click the preview\u2026':'Place on plan')+'</button><button type="button" class="secondary" data-fixture-remove="'+i+'">Remove</button></div>').join(''):'<p class="muted">No fixtures yet.</p>')+'<div class="actions">'+FIXTURE_TYPES.map(([k,l])=>'<button type="button" class="secondary" data-fixture-add="'+k+'">+ '+l+'</button>').join('')+'</div></fieldset>';}
function freeSpotFor(w,h){const pts=outline(segments,closed).points;if(pts.length<3)return {x:1000,y:1000};const xs=pts.map(p=>p.x),ys=pts.map(p=>p.y),yard=editingYard;const taken=[...(fixtureRows??[]),...(yard?state.containers.filter(c=>c.location===yard.id&&!c.support).map(c=>({x:c.x,y:c.y,w:c.rotation===90?c.envelopeWidth:c.envelopeLength,h:c.rotation===90?c.envelopeLength:c.envelopeWidth})):[]),{...(yard?.loading??{x:1000,y:1000}),w:2000,h:1500}];for(let y=Math.ceil(Math.min(...ys)/500)*500;y<Math.max(...ys);y+=500)for(let x=Math.ceil(Math.min(...xs)/500)*500;x<Math.max(...xs);x+=500){const r={x,y,w,h};if(fitsPolygon(r,pts)&&!taken.some(t=>overlap(r,t)))return {x,y};}return {x:Math.ceil(Math.min(...xs)/500)*500,y:Math.ceil(Math.min(...ys)/500)*500};}

export const __test={setState(s,a){state=s;account=a;},workersView:()=>workersView(),setView(v){view=v;},homeView:()=>homeView(),detail:()=>detail(),setSelected(id){selected=id;},setLayoutDraft(d){layoutDraft=d;}};
